function getUnifiedTaskType(type) {
  const value = String(type || "")
    .replace(/\s*\((документарный|физический)\)\s*$/i, "")
    .trim();
  return /^постановка\s+в\s+залог$/i.test(value) ? TASK_TYPE_REGISTRATION : value;
}

const TASK_STATUSES = ["Новая", "Назначена", "В работе", "Ожидание", "Отложена", "Завершена"];
const LEGACY_TASK_STATUS_REWORK = ["На", "доработке"].join(" ");
const LEGACY_TASK_STATUS_APPROVAL = ["На", "согласовании"].join(" ");

const IMPORT_TEMPLATE_COLUMNS = [
  "Идентификационный код",
  "Идентификатор в АБС",
  "Вид залога",
  "Наименование",
  "Описание",
  "Профильный идентификатор объекта",
  "Статус объекта",
  "Залогодатель",
  "ИНН залогодателя",
  "Номер договора",
  "Продукт / сделка",
  "Адрес / местонахождение",
  "Код страны по ОКСМ",
  "Код территории по ОКАТО",
  "Город",
  "Признак включения в учетные/отчетные данные",
  "Категория качества",
  "Признак обеспечения",
  "Идентификационный код группы"
];

function normalizeTaskStatus(status) {
  if (status === LEGACY_TASK_STATUS_REWORK) return "Ожидание";
  if (status === LEGACY_TASK_STATUS_APPROVAL) return "Назначена";
  return TASK_STATUSES.includes(status) ? status : (status || "Назначена");
}

function normalizeTaskHistoryEvent(event = {}) {
  const status = normalizeTaskStatus(event.status);
  return {
    ...event,
    status,
    oldValue: event.oldValue || event.valueBefore || "",
    newValue: event.newValue || event.valueAfter || event.result || status || "",
    comment: event.comment || event.reason || ""
  };
}

function getImportTemplateValue(row, column) {
  const typeLabel = getCollateralTypeLabel({ type: row.type });
  const profileIdentifier = row.profileIdentifier
    || row.identifierValue
    || row.collateralId
    || row.vin
    || row.cadastralNumber
    || row.factoryNumber
    || "";
  const values = {
    "Идентификационный код": row.collateralId,
    "Идентификатор в АБС": row.absId || row.absIdentifier || "",
    "Вид залога": typeLabel,
    "Наименование": row.name || row.object || row.type,
    "Описание": row.description || row.message,
    "Профильный идентификатор объекта": profileIdentifier,
    "Статус объекта": COLLATERAL_STATUS_OPTIONS.includes(row.objectStatus) ? row.objectStatus : "Новый",
    "Залогодатель": row.owner,
    "ИНН залогодателя": row.ownerInn,
    "Номер договора": row.contract,
    "Продукт / сделка": row.product || row.dealProduct,
    "Адрес / местонахождение": row.address,
    "Код страны по ОКСМ": row.countryCode,
    "Код территории по ОКАТО": row.okato,
    "Город": row.city || getCityFromAddress(row.address),
    "Признак включения в учетные/отчетные данные": row.includeReportData || row.include310 || "Да",
    "Категория качества": row.qualityCategory,
    "Признак обеспечения": row.pledgeSign,
    "Идентификационный код группы": row.groupCode
  };
  return values[column] || "-";
}

function normalizeTaskRecord(task) {
  if (!task) return task;
  const { approval, ...rest } = task;
  return {
    ...rest,
    type: getUnifiedTaskType(task.type),
    status: normalizeTaskStatus(task.status),
    history: Array.isArray(task.history) ? task.history.map(normalizeTaskHistoryEvent) : []
  };
}

function readSavedTaskState() {
  try {
    const raw = localStorage.getItem(TASK_STATE_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed?.tasks) ? parsed.tasks.filter((task) => task?.id) : [];
  } catch (error) {
    console.warn("Не удалось прочитать сохраненное состояние задач", error);
    return [];
  }
}

function readSavedApplicationState() {
  try {
    const raw = localStorage.getItem(TASK_STATE_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed?.applications) ? parsed.applications.filter((item) => item?.id && item?.number) : [];
  } catch (error) {
    console.warn("Не удалось прочитать сохраненное состояние заявок", error);
    return [];
  }
}

const SAVED_TASK_DEFAULT_OBJECT_FIELDS = ["inspectionAnswers", "inspectionChecklistComments", "inspectionResolutions"];

function isPlainObject(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function mergeSavedValueWithDefaults(defaultValue, savedValue) {
  if (savedValue === undefined || savedValue === null) return clone(defaultValue);
  if (Array.isArray(defaultValue)) return Array.isArray(savedValue) ? savedValue : clone(defaultValue);
  if (isPlainObject(defaultValue)) {
    if (!isPlainObject(savedValue)) return clone(defaultValue);
    const merged = {};
    Object.keys(defaultValue).forEach((key) => {
      merged[key] = mergeSavedValueWithDefaults(defaultValue[key], savedValue[key]);
    });
    Object.keys(savedValue).forEach((key) => {
      if (!(key in merged)) merged[key] = clone(savedValue[key]);
    });
    return merged;
  }
  return savedValue;
}

function mergeSavedTaskWithBase(task, baseTask) {
  const merged = {
    ...(baseTask || {}),
    ...task,
    history: Array.isArray(task.history) ? task.history : (baseTask?.history || [])
  };
  SAVED_TASK_DEFAULT_OBJECT_FIELDS.forEach((field) => {
    if (baseTask?.[field] !== undefined) {
      merged[field] = mergeSavedValueWithDefaults(baseTask[field], task[field]);
    }
  });
  return merged;
}

function normalizeDataApplicationSingleClient(data, application) {
  if (!application) return application;
  const deals = Array.isArray(application.deals) ? application.deals : [];
  const contractIds = new Set([...(application.contractIds || []), application.contractId].filter(Boolean));
  parseListValue(application.contractNumber).forEach((number) => {
    const contract = findDataContract(data, number);
    if (contract) contractIds.add(contract.id);
  });
  deals.forEach((row) => {
    if (row.contractId) contractIds.add(row.contractId);
    const contract = findDataContract(data, row.contractNumber);
    if (contract) contractIds.add(contract.id);
  });
  const firstContract = [...contractIds].map((id) => findDataContract(data, id)).find(Boolean);
  const savedClientNames = Array.isArray(application.clientNames) ? application.clientNames : parseListValue(application.clientNames);
  const savedClientInns = Array.isArray(application.clientInns) ? application.clientInns : parseListValue(application.clientInns);
  const clientName = application.clientName
    || application.participantName
    || savedClientNames[0]
    || deals.find((row) => row.clientName)?.clientName
    || firstContract?.clientName
    || "";
  const clientInn = application.participantInn
    || application.inn
    || savedClientInns[0]
    || deals.find((row) => row.inn)?.inn
    || firstContract?.inn
    || "";
  return {
    ...application,
    clientName,
    clientNames: clientName ? [clientName] : [],
    participantName: clientName,
    participantInn: clientInn,
    clientInns: clientInn ? [clientInn] : [],
    deals: deals.map((row) => ({
      ...row,
      clientName,
      inn: clientInn
    }))
  };
}

function buildRuntimeData() {
  const data = clone(initialData);
  data.applications = data.applications || [];
  const savedApplications = readSavedApplicationState();
  if (savedApplications.length) {
    const savedIds = new Set(savedApplications.map((item) => item.id));
    const savedNumbers = new Set(savedApplications.map((item) => item.number));
    data.applications = [
      ...savedApplications,
      ...data.applications.filter((item) => !savedIds.has(item.id) && !savedNumbers.has(item.number))
    ];
  }
  data.applications = data.applications.map((application) => normalizeDataApplicationSingleClient(data, application));
  data.tasks = data.tasks.map(normalizeTaskRecord);
  const savedTasks = readSavedTaskState().map(normalizeTaskRecord);
  if (savedTasks.length) {
    const baseById = new Map(data.tasks.map((task) => [task.id, task]));
    const savedIds = new Set(savedTasks.map((task) => task.id));
    data.tasks = [
      ...savedTasks.map((task) => mergeSavedTaskWithBase(task, baseById.get(task.id))),
      ...data.tasks.filter((task) => !savedIds.has(task.id))
    ];
  }
  return ensureApplicationsHaveInitialTasks(enrichTaskApplications(ensureTaskRegistryExamples(sanitizeMvp1Data(data))));
}

function ensureTaskRegistryExamples(data) {
  const tasks = data.tasks || [];
  const assignments = [
    { id: "TSK-2026-1170", assignee: "Алексей Соколов", status: "В работе" },
    { id: "TSK-2026-1171", assignee: "Алексей Соколов", status: "Назначена" },
    { id: "TSK-2026-1174", assignee: "Алексей Соколов", status: "В работе" },
    { id: "TSK-2026-1161", assignee: "Сергей Иванов", status: "Назначена" },
    { id: "TSK-2026-1140", assignee: "Мария Петрова", status: "Назначена" },
    { id: "TSK-2026-1055", assignee: "Елена Морозова", status: "В работе" }
  ];
  assignments.forEach((patch) => {
    const task = tasks.find((item) => item.id === patch.id);
    if (task) Object.assign(task, patch);
  });
  ensureExampleTask(data, "TSK-2026-1180", "TSK-2026-1173", {
    title: "Завершить оценку смешанного пула залогов Столичный Девелопмент",
    assignee: "Алексей Соколов",
    status: "Завершена",
    dueDate: "2026-08-22",
    createdAt: "2026-08-20",
    sla: "В срок",
    result: "Экспертное заключение по задаче сформировано, рыночная, залоговая и справедливая стоимость рассчитаны по всем объектам.",
    history: [
      { date: "2026-08-22 16:40", user: "Алексей Соколов", action: "Завершена", status: "Завершена", comment: "Заключение проверено и сохранено в задаче." },
      { date: "2026-08-20 10:15", user: "Система", action: "Создана задача", status: "Назначена", comment: "Первая задача создана автоматически из заявки на оценку." }
    ]
  });
  ensureExampleTask(data, "TSK-2026-1181", "TSK-2026-1174", {
    title: "Завершить регистрацию залога квартиры и оборудования по договору MX-26/405",
    assignee: "Елена Морозова",
    status: "Завершена",
    dueDate: "2026-08-23",
    createdAt: "2026-08-21",
    sla: "В срок",
    registrationStatuses: {
      "COL-045": "Зарегистрировано",
      "COL-048": "Зарегистрировано"
    },
    result: "Регистрационные действия выполнены, сведения переданы в АБС, связь объектов с договором подтверждена.",
    history: [
      { date: "2026-08-23 15:20", user: "Елена Морозова", action: "Завершена", status: "Завершена", comment: "Регистрация подтверждена по всем объектам." },
      { date: "2026-08-21 09:35", user: "Система", action: "Создана задача", status: "Назначена", comment: "Первая задача создана автоматически из заявки на регистрацию." }
    ]
  });
  return data;
}

function ensureExampleTask(data, id, templateId, overrides = {}) {
  if ((data.tasks || []).some((task) => task.id === id)) return;
  const template = (data.tasks || []).find((task) => task.id === templateId);
  if (!template) return;
  data.tasks.push(normalizeTaskRecord({
    ...clone(template),
    ...overrides,
    id,
    documents: clone(overrides.documents || template.documents || []),
    marketAnalogManualValues: clone(overrides.marketAnalogManualValues || template.marketAnalogManualValues || {}),
    registrationStatuses: clone(overrides.registrationStatuses || template.registrationStatuses || {}),
    history: clone(overrides.history || template.history || [])
  }));
}

function sanitizeMvp1Data(data) {
  data.tasks = (data.tasks || [])
    .map(normalizeTaskRecord)
    .filter(isMvp1TaskAllowed)
    .map(sanitizeMvp1Task);
  data.integrations = (data.integrations || [])
    .filter((item) => MVP1_INTEGRATION_IDS.has(item.id))
    .map(sanitizeMvp1Integration);
  data.audit = (data.audit || []).filter((item) => {
    const text = `${item.object || ""} ${item.action || ""} ${item.source || ""}`;
    return !/мониторинг|TSK-2026-1081|TSK-2026-1022/i.test(text);
  });
  return data;
}

function enrichTaskApplications(data) {
  data.applications = data.applications || [];
  data.tasks = (data.tasks || []).map((task) => {
    const collaterals = getDataTaskCollaterals(data, task);
    const contract = findDataContract(data, task.contractId || task.contractNumber)
      || findDataContract(data, collaterals[0]?.contractIds?.[0]);
    const application = findDataApplicationForTask(data, task, contract, collaterals)
      || ensureDataApplicationForTask(data, task, contract, collaterals);
    if (!application) return task;
    updateDataApplicationLinks(application, task, contract, collaterals);
    return {
      ...task,
      applicationId: application.id,
      applicationNumber: application.number,
      applicationSource: application.source || task.applicationSource || "Ручное создание",
      contractNumber: task.contractNumber || contract?.number || application.contractNumber || "",
      dealClientName: task.dealClientName || application.clientName || application.participantName || contract?.clientName || "",
      dealClientInn: task.dealClientInn || application.participantInn || contract?.inn || collaterals[0]?.clientId || "",
      dealProduct: task.dealProduct || application.product || contract?.product || "",
      dealLimit: task.dealLimit || application.limit || contract?.limit || "",
      dealCurrency: task.dealCurrency || application.currency || contract?.currency || "RUB",
      participantName: task.participantName || application.participantName || contract?.clientName || collaterals[0]?.clientName || "",
      participantInn: task.participantInn || application.participantInn || contract?.inn || collaterals[0]?.clientId || ""
    };
  });
  return data;
}

function ensureApplicationsHaveInitialTasks(data) {
  data.applications = data.applications || [];
  data.tasks = data.tasks || [];
  const validApplications = [];
  data.applications.forEach((application) => {
    const linkedTasks = getDataApplicationTasks(data, application);
    if (linkedTasks.length) {
      application.taskIds = uniqueItems([...(application.taskIds || []), ...linkedTasks.map((task) => task.id)]);
      validApplications.push(application);
      return;
    }
    const initialTask = buildDataInitialTaskForApplication(data, application);
    if (!initialTask) return;
    data.tasks.unshift(initialTask);
    application.taskIds = uniqueItems([...(application.taskIds || []), initialTask.id]);
    validApplications.push(application);
  });
  data.applications = validApplications;
  return data;
}

function getDataApplicationTasks(data, application) {
  if (!application) return [];
  const ids = new Set(application.taskIds || []);
  return (data.tasks || []).filter((task) =>
    ids.has(task.id)
    || task.applicationId === application.id
    || task.applicationNumber === application.number
  );
}

function buildDataInitialTaskForApplication(data, application) {
  const collateralIds = getDataApplicationCollateralIds(data, application);
  if (!collateralIds.length) return null;
  const primaryCollateralId = collateralIds[0];
  const collaterals = collateralIds.map((id) => (data.collaterals || []).find((item) => item.id === id)).filter(Boolean);
  const primaryCollateral = collaterals[0] || null;
  const contract = getDataApplicationPrimaryContract(data, application, primaryCollateral);
  const taskType = getApplicationInitialTaskType(application.applicationType, application.applicationSubtype);
  const createdAt = application.createdAt || formatTaskHistoryDate(new Date());
  const clientName = application.clientName || application.participantName || contract?.clientName || primaryCollateral?.clientName || "Клиент не указан";
  const clientInn = application.participantInn || application.inn || contract?.inn || primaryCollateral?.clientId || "";
  const product = application.product || application.products?.[0] || contract?.product || "";
  const limit = parseNumericInput(application.limit ?? contract?.limit ?? 0);
  const currency = application.currency || contract?.currency || "RUB";
  const task = normalizeTaskRecord({
    id: getNextDataTaskId(data, application),
    type: taskType,
    title: `${taskType} по заявке ${application.number || application.id}`,
    collateralId: primaryCollateralId,
    collateralIds: collateralIds.length > 1 ? collateralIds : undefined,
    applicationId: application.id,
    applicationNumber: application.number,
    applicationSource: application.source || "Ручное создание",
    dealClientName: clientName,
    dealClientInn: clientInn,
    dealProduct: product,
    dealLimit: limit,
    dealCurrency: currency,
    participantName: application.participantName || clientName,
    participantInn: clientInn,
    contractId: contract?.id || application.contractId || "",
    contractNumber: application.contractNumber || contract?.number || "",
    assignee: getDefaultTaskAssigneeForType(taskType),
    status: "Назначена",
    dueDate: getDefaultInitialTaskDueDate(createdAt),
    createdAt,
    sla: "Норма",
    priority: "Средний",
    source: "Заявка",
    route: ["Заявка", "Специалист", "Руководитель"],
    result: `Первая задача создана автоматически из заявки ${application.number || application.id}.`,
    autoInitiated: true,
    inspectionFormat: getApplicationInitialInspectionFormat(application.applicationType, application.applicationSubtype),
    registrationScenario: isRegistrationTaskType(taskType) ? application.registrationScenario || application.applicationSubtype || REGISTRATION_SCENARIO_MOVABLE : "",
    documents: clone(application.documents || []),
    history: [{
      date: createdAt,
      user: "Система",
      action: "Создана задача",
      status: "Назначена",
      oldValue: "-",
      newValue: "Назначена",
      comment: `Первая задача создана автоматически из заявки ${application.number || application.id}.`
    }]
  });
  return task;
}

function getDataApplicationCollateralIds(data, application) {
  const ids = uniqueItems([
    ...(application?.collateralIds || []),
    ...(Array.isArray(application?.deals) ? application.deals.flatMap((row) => [
      ...(row.collateralIds || []),
      ...parseListValue(row.collateralId)
    ]) : [])
  ].filter(Boolean));
  return ids.filter((id) => (data.collaterals || []).some((item) => item.id === id));
}

function getDataApplicationPrimaryContract(data, application, primaryCollateral) {
  const dealRows = Array.isArray(application?.deals) ? application.deals : [];
  const contractIds = uniqueItems([
    application?.contractId,
    ...(application?.contractIds || []),
    ...dealRows.map((row) => row.contractId),
    ...(primaryCollateral?.contractIds || [])
  ].filter(Boolean));
  const directContract = contractIds.map((id) => findDataContract(data, id)).find(Boolean);
  if (directContract) return directContract;
  const contractNumber = application?.contractNumber || dealRows.find((row) => row.contractNumber)?.contractNumber || "";
  return findDataContract(data, contractNumber);
}

function getNextDataTaskId(data, application) {
  const used = new Set((data.tasks || []).map((task) => task.id));
  const suffix = Number(String(application?.id || application?.number || "").match(/(\d{3,})\b/g)?.pop() || 0);
  let next = Math.max(1200, suffix ? suffix + 1000 : 1200 + used.size);
  let id = `TSK-2026-${String(next).padStart(4, "0")}`;
  while (used.has(id)) {
    next += 1;
    id = `TSK-2026-${String(next).padStart(4, "0")}`;
  }
  return id;
}

function getDataTaskCollateralIds(task) {
  return task?.collateralIds?.length ? task.collateralIds : [task?.collateralId].filter(Boolean);
}

function getDataTaskCollaterals(data, task) {
  return getDataTaskCollateralIds(task)
    .map((id) => (data.collaterals || []).find((item) => item.id === id))
    .filter(Boolean);
}

function findDataContract(data, idOrNumber) {
  const value = String(idOrNumber || "").trim().toLowerCase();
  if (!value) return null;
  return (data.contracts || []).find((item) => String(item.id || "").toLowerCase() === value || String(item.number || "").toLowerCase() === value) || null;
}

function findDataApplication(data, idOrNumber) {
  const value = String(idOrNumber || "").trim();
  if (!value) return null;
  return (data.applications || []).find((item) => item.id === value || item.number === value) || null;
}

function findDataApplicationByContract(data, contract) {
  if (!contract) return null;
  return (data.applications || []).find((item) =>
    item.contractId === contract.id
    || item.contractNumber === contract.number
    || (item.contractIds || []).includes(contract.id)
  ) || null;
}

function findDataApplicationByCollaterals(data, collaterals) {
  const ids = new Set(collaterals.map((item) => item.id));
  if (!ids.size) return null;
  return (data.applications || []).find((item) => (item.collateralIds || []).some((id) => ids.has(id))) || null;
}

function findDataApplicationForTask(data, task, contract, collaterals) {
  return findDataApplication(data, task.applicationId || task.applicationNumber)
    || findDataApplicationByContract(data, contract)
    || findDataApplicationByCollaterals(data, collaterals);
}

function ensureDataApplicationForTask(data, task, contract, collaterals) {
  if (!contract && !collaterals.length) return null;
  const { id, number } = getNextDataApplicationIdentity(data);
  const clientName = contract?.clientName || collaterals[0]?.clientName || task.client || "Клиент не указан";
  const product = contract?.product || "";
  const initiator = task.autoInitiated ? "Система" : task.initiator || task.client || "Анна Кузнецова";
  const applicationType = getApplicationTypeForTaskType(task.type);
  const applicationSubtype = getApplicationSubtypeForTaskType(task.type);
  const application = {
    id,
    number,
    createdAt: task.createdAt || getTaskCreatedDateTime(task),
    source: task.applicationSource || "Ручное создание",
    applicationType,
    applicationSubtype,
    applicationPurpose: getDefaultApplicationPurpose(applicationType, applicationSubtype),
    initiator,
    initiatorSegment: getDataApplicationInitiatorSegment({ initiator, product }),
    clientName,
    clientNames: [clientName].filter(Boolean),
    participantName: clientName,
    participantInn: contract?.inn || collaterals[0]?.clientId || "",
    clientInns: [contract?.inn || collaterals[0]?.clientId || ""].filter(Boolean),
    product,
    products: [product].filter(Boolean),
    limit: contract?.limit || "",
    currency: contract?.currency || "RUB",
    status: "В работе",
    decisionStatus: getDataApplicationDecisionStatus(task),
    contractId: contract?.id || "",
    contractNumber: contract?.number || task.contractNumber || "",
    collateralIds: collaterals.map((item) => item.id),
    taskIds: task.id ? [task.id] : []
  };
  data.applications.push(application);
  return application;
}

function getNextDataApplicationIdentity(data) {
  const used = new Set((data.applications || []).flatMap((item) => [item.id, item.number]));
  const max = (data.applications || []).reduce((result, item) => {
    const number = Number(String(`${item.id || ""} ${item.number || ""}`).match(/(\d{3,})\b/g)?.pop() || 0);
    return Math.max(result, number);
  }, 419);
  let next = max + 1;
  let id = `APP-2026-${String(next).padStart(4, "0")}`;
  let number = `APP-26/${String(next).padStart(4, "0")}`;
  while (used.has(id) || used.has(number)) {
    next += 1;
    id = `APP-2026-${String(next).padStart(4, "0")}`;
    number = `APP-26/${String(next).padStart(4, "0")}`;
  }
  return { id, number };
}

function getDataApplicationDecisionStatus(task) {
  if (isPledgeOperationTaskType(task?.type)) return "Положительное решение по сделке";
  if (/Заверш/i.test(task?.status || "")) return "Заключение залоговой службы сформировано";
  return "Ожидается заключение залоговой службы";
}

function getDataApplicationInitiatorSegment(application) {
  if (application?.initiatorSegment) return application.initiatorSegment;
  if (/система/i.test(String(application?.initiator || ""))) return "Автоматическое создание";
  const product = String(application?.product || "").toLowerCase();
  if (/ипотеч|рознич/i.test(product)) return "Розничный бизнес";
  if (/гарант|экспорт|корпоратив/i.test(product)) return "Корпоративный бизнес";
  return "МСБ";
}

function updateDataApplicationLinks(application, task, contract, collaterals) {
  if (!application.createdAt) application.createdAt = task.createdAt || getTaskCreatedDateTime(task);
  if (contract && !application.contractId) application.contractId = contract.id;
  if (contract && !application.contractNumber) application.contractNumber = contract.number;
  if (contract) application.contractIds = [...new Set([...(application.contractIds || []), contract.id])];
  if (!application.clientName) application.clientName = application.participantName || contract?.clientName || collaterals[0]?.clientName || "";
  application.clientNames = application.clientName ? [application.clientName] : [];
  if (!application.participantName) application.participantName = application.clientName;
  if (!application.participantInn) application.participantInn = application.inn || contract?.inn || collaterals[0]?.clientId || "";
  application.clientInns = application.participantInn ? [application.participantInn] : [];
  if (contract && !application.product) application.product = contract.product || "";
  if (contract) application.products = uniqueItems([...(application.products || []), application.product, contract.product].filter(Boolean));
  if (!application.initiatorSegment) application.initiatorSegment = getDataApplicationInitiatorSegment(application);
  if (contract && !application.limit) application.limit = contract.limit || "";
  application.currency = application.currency || contract?.currency || "RUB";
  application.collateralIds = [...new Set([...(application.collateralIds || []), ...collaterals.map((item) => item.id)])];
  application.taskIds = [...new Set([...(application.taskIds || []), task.id].filter(Boolean))];
}

function sanitizeMvp1Integration(item) {
  return {
    ...item,
    status: item.status === "Прототип" ? "Настроен" : item.status,
    logs: (item.logs || []).map((log) => ({
      ...log,
      result: log.result === "Прототип" ? "Настроен" : log.result,
      message: replaceNonMvp1Text(log.message)
    }))
  };
}

function isMvp1TaskAllowed(task) {
  if (!MVP1_TASK_TYPES.has(task?.type)) return false;
  if (isMonitoringTaskType(task.type)) return isMvp1PhysicalMonitoringTask(task) || isMvp1DocumentaryMonitoringTask(task);
  return true;
}

function isMvp1DocumentaryMonitoringTask(task) {
  return /внеплан/i.test(String(task?.type || "")) && isDocumentaryInspectionTask(task);
}

function isMvp1PhysicalMonitoringTask(task) {
  const routeText = Array.isArray(task?.route) ? task.route.join(" ") : "";
  const text = `${task?.title || ""} ${task?.result || ""} ${task?.source || ""} ${routeText}`.toLowerCase();
  if (/документар|сверить документы|рыночн|цена|стоимост|циан|яндекс/i.test(text)) return false;
  return /выезд|фото|осмотр|склад|остат|парт|местонахожд|фактическ|состояни|поголов|крс|стад/i.test(text);
}

function sanitizeMvp1Task(task) {
  const route = getMvp1TaskRoute(task);
  const baseTask = initialData.tasks.find((item) => item.id === task.id) || task;
  return {
    ...task,
    title: replaceNonMvp1Text(task.title),
    result: replaceNonMvp1Text(task.result),
    source: getMvp1TaskSource(task.source),
    autoInitiated: task.autoInitiated === true || isTaskCreatedAutomatically(baseTask),
    route,
    mobileKind: undefined,
    parentTaskId: isMobileInspectionTaskType(task.type) ? undefined : task.parentTaskId,
    history: (task.history || []).map((event) => ({
      ...normalizeTaskHistoryEvent(event),
      user: replaceNonMvp1Text(event.user),
      comment: replaceNonMvp1Text(event.comment)
    }))
  };
}

function getMvp1TaskSource(source) {
  const value = String(source || "");
  if (/АБС/i.test(value)) return "АБС";
  if (/Авто\.ру/i.test(value)) return "Авто.ру";
  if (/Авито/i.test(value)) return "Авито";
  if (/Email|Почтов/i.test(value)) return "Вручную";
  return "Вручную";
}

function getMvp1TaskRoute(task) {
  if (isPledgeOperationTaskType(task.type)) return ["Специалист", "АБС"];
  if (task.type === "Единичная переоценка" || task.type === "Списочная переоценка") return ["Специалист", "Руководитель"];
  if (isMonitoringTaskType(task.type)) return ["Специалист"];
  return ["Специалист"];
}

function replaceNonMvp1Text(value) {
  if (value === undefined || value === null) return value;
  return String(value)
    .replace(/Циан|Яндекс Недвижимость|Сервис данных ЕГРН|Мобильный оценщик/gi, "рыночный источник")
    .replace(/Розничный, лизинговый или МСБ-конвейер|Конвейер/gi, "Ручная инициация")
    .replace(/Планировщик|Расписание/gi, "Ручная инициация")
    .replace(/Триггер мониторинга|Monitoring|Триггер/gi, "Ручная инициация")
    .replace(/ЕСМ Банка/gi, "досье Банка")
    .replace(/Мобильный АРМ|Мобильный осмотр|Выездной сотрудник/gi, "АРМ специалиста")
    .replace(/\s*в MVP1/gi, "")
    .replace(/MVP1/gi, "");
}

function isKnownRole(roleId) {
  return roles.some((role) => role.id === roleId);
}

function getInitialRoleId() {
  try {
    const savedRole = sessionStorage.getItem(ROLE_STATE_STORAGE_KEY);
    if (isKnownRole(savedRole)) return savedRole;
  } catch (error) {
    console.warn("Не удалось прочитать выбранную роль", error);
  }

  const roleFromUrl = new URLSearchParams(window.location.search).get("role");
  if (isKnownRole(roleFromUrl)) return roleFromUrl;
  return "evaluationManager";
}

function rememberSelectedRole(roleId) {
  try {
    if (isKnownRole(roleId)) sessionStorage.setItem(ROLE_STATE_STORAGE_KEY, roleId);
  } catch (error) {
    console.warn("Не удалось сохранить выбранную роль", error);
  }
}

