function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function formatMoney(value, currency = "RUB") {
  const amount = Number(value || 0).toLocaleString("ru-RU");
  const displayCurrency = currency === "RUB" ? "₽" : currency;
  return `${amount} ${displayCurrency}`;
}

function badge(text, tone = "") {
  const value = String(text ?? "-");
  const inferred = tone || badgeTone(value);
  return `<span class="badge badge-${inferred}">${escapeHtml(value)}</span>`;
}

function badgeTone(value) {
  const text = String(value).toLowerCase();
  if (/(крит|проср|ошиб|не обеспеч|возврат|доработ)/i.test(text)) return "danger";
  if (/(истека|частич|предуп|отлож|в работе|высок)/i.test(text)) return "warn";
  if (/(действ|оплачен|заверш|успеш|полное|хорош)/i.test(text)) return "ok";
  if (/(назнач|сегодня|средн|норма|инфо)/i.test(text)) return "info";
  return "neutral";
}

function getRole() {
  return roles.find((item) => item.id === state.roleId) || roles[0];
}

function getSwitcherRoles() {
  return roles.filter((item) => item.id !== "admin");
}

function renderRoleSwitcher(role) {
  return `
    <div class="role-box">
      <span class="role-user" title="${escapeHtml(role.user)}">${escapeHtml(role.user)}</span>
      <select data-action="change-role">
        ${getSwitcherRoles().map((item) => `<option value="${item.id}" ${item.id === role.id ? "selected" : ""}>${escapeHtml(item.label)}</option>`).join("")}
      </select>
    </div>
  `;
}

const TASK_REGISTRY_DIRECTIONS = {
  evaluation: {
    id: "evaluation",
    navId: "tasksEvaluation",
    label: "Оценка",
    title: "Реестр задач оценки",
    description: "Задачи оценки и переоценки объектов залога.",
    path: "/app/tasks/evaluation",
    permission: "evalTaskView"
  },
  inspection: {
    id: "inspection",
    navId: "tasksInspection",
    label: "Осмотр",
    title: "Реестр задач осмотра",
    description: "Задачи физического и документарного осмотра, мониторинга и проверок по объектам залога.",
    path: "/app/tasks/inspection",
    permission: "inspectTaskView"
  },
  registration: {
    id: "registration",
    navId: "tasksRegistration",
    label: "Регистрация",
    title: "Реестр задач регистрации залога",
    description: "Задачи регистрации залога и контроля регистрационных действий.",
    path: "/app/tasks/registration",
    permission: "regTaskView"
  }
};

function hasPermission(role, permission) {
  if (!permission) return true;
  return Boolean(role?.permissions?.[permission]);
}

function canViewNavItem(item, role) {
  return Boolean(item && (hasPermission(role, item.permission) || role?.menu?.includes(item.id)));
}

function getAvailableNavItems(role) {
  return navItems.filter((item) => canViewNavItem(item, role) && item.id !== "mobileEmployee");
}

function getTaskDirectionConfig(direction) {
  return TASK_REGISTRY_DIRECTIONS[direction] || TASK_REGISTRY_DIRECTIONS.evaluation;
}

function getTaskDirectionFromPath(path) {
  if (path === "/app/tasks/evaluation") return "evaluation";
  if (path === "/app/tasks/inspection") return "inspection";
  if (path === "/app/tasks/registration") return "registration";
  return "";
}

function canViewTaskDirection(direction, role = getRole()) {
  const config = TASK_REGISTRY_DIRECTIONS[direction];
  return Boolean(config && hasPermission(role, config.permission));
}

function getAvailableTaskDirections(role = getRole()) {
  return Object.keys(TASK_REGISTRY_DIRECTIONS).filter((direction) => canViewTaskDirection(direction, role));
}

function getDefaultRouteForRole(role = getRole()) {
  const taskDirection = getAvailableTaskDirections(role)[0];
  if (taskDirection) return getTaskDirectionConfig(taskDirection).path;
  if (hasPermission(role, "appRegView")) return "/app/applications";
  if (hasPermission(role, "collateralView")) return "/app/collaterals";
  return "/app/applications";
}

function getTaskDirection(task) {
  const type = getUnifiedTaskType(task?.type || "");
  if (isPledgeOperationTaskType(type)) return "registration";
  if (isInspectionTaskType(type) || isDefectInspectionTaskType(type) || isMobileInspectionTaskType(type) || isMonitoringTaskType(type) || /птс/i.test(type)) return "inspection";
  if (isRevaluationTaskType(type) || /оцен/i.test(type)) return "evaluation";
  return "evaluation";
}

function canViewTask(task, role = getRole()) {
  return canViewTaskDirection(getTaskDirection(task), role);
}

function getRoute() {
  return window.location.hash.replace(/^#/, "") || getDefaultRouteForRole(getRole());
}

function parseRoute() {
  const [path, query = ""] = getRoute().split("?");
  return { path, query: new URLSearchParams(query) };
}

function updateCollateralTabRoute(tab) {
  state.collateralTab = tab || "overview";
  const { path, query } = parseRoute();
  if (!path.startsWith("/app/collaterals/")) {
    render();
    return;
  }
  query.set("tab", state.collateralTab);
  const route = `${path}?${query.toString()}`;
  if (getRoute() === route) render();
  else window.location.hash = route;
}

function getTask(id) {
  return state.data.tasks.find((item) => item.id === id);
}

function getCollateral(id) {
  return state.data.collaterals.find((item) => item.id === id);
}

function getContract(id) {
  return state.data.contracts.find((item) => item.id === id);
}

function getContractByNumber(number) {
  const value = String(number || "").trim().toLowerCase();
  if (!value) return null;
  return state.data.contracts.find((item) => String(item.number || "").toLowerCase() === value || String(item.id || "").toLowerCase() === value) || null;
}

function getApplication(id) {
  return (state.data.applications || []).find((item) => item.id === id || item.number === id);
}

function getApplicationByIdOrNumber(value) {
  return getApplication(value) || getApplicationByNumber(value);
}

function getApplicationByNumber(number) {
  const value = String(number || "").trim();
  if (!value) return null;
  return (state.data.applications || []).find((item) => item.number === value || item.id === value) || null;
}

function getApplicationByContract(contractIdOrNumber) {
  const value = String(contractIdOrNumber || "").trim().toLowerCase();
  if (!value) return null;
  return (state.data.applications || []).find((item) =>
    String(item.contractId || "").toLowerCase() === value
    || String(item.contractNumber || "").toLowerCase() === value
    || parseListValue(item.contractNumber).some((number) => number.toLowerCase() === value)
    || (item.contractIds || []).some((contractId) => String(contractId || "").toLowerCase() === value)
  ) || null;
}

function getApplicationTasks(application) {
  if (!application) return [];
  const ids = new Set(application.taskIds || []);
  return (state.data.tasks || [])
    .filter((task) => ids.has(task.id) || task.applicationId === application.id || task.applicationNumber === application.number)
    .sort((a, b) => String(getTaskCreatedDateTime(b)).localeCompare(String(getTaskCreatedDateTime(a))));
}

function getApplicationCollaterals(application) {
  if (!application) return [];
  const ids = new Set(application.collateralIds || []);
  getApplicationTasks(application).forEach((task) => getTaskCollaterals(task).forEach((collateral) => ids.add(collateral.id)));
  return [...ids].map(getCollateral).filter(Boolean);
}

function getApplicationContracts(application) {
  if (!application) return [];
  const ids = new Set([
    ...(application.contractIds || []),
    application.contractId,
    ...getApplicationDealRows(application).map((row) => row.contractId)
  ].filter(Boolean));
  parseListValue(application.contractNumber).forEach((number) => {
    const contract = getContractByNumber(number);
    if (contract) ids.add(contract.id);
  });
  getApplicationDealRows(application).forEach((row) => {
    const contract = getContractByNumber(row.contractNumber);
    if (contract) ids.add(contract.id);
  });
  getApplicationTasks(application).forEach((task) => {
    if (task.contractId) ids.add(task.contractId);
    const contract = getContractByNumber(task.contractNumber);
    if (contract) ids.add(contract.id);
  });
  return [...ids].map(getContract).filter(Boolean);
}

function getApplicationCreatedDate(application) {
  if (application?.createdAt) return application.createdAt;
  const dates = getApplicationTasks(application)
    .map(getTaskCreatedDateTime)
    .filter((value) => value && value !== "-")
    .sort((a, b) => String(a).localeCompare(String(b)));
  return dates[0] || "-";
}

function getApplicationClientNames(application) {
  const directNames = uniqueItems([
    application?.clientName,
    application?.participantName,
    ...(application?.clientNames || [])
  ].filter(Boolean));
  if (directNames.length) return directNames.slice(0, 1);
  const fallback = getApplicationDealRows(application).find((row) => row.clientName)?.clientName
    || getApplicationContracts(application).find((contract) => contract.clientName)?.clientName;
  return fallback ? [fallback] : [];
}

function getApplicationClientName(application) {
  return getApplicationClientNames(application).join(", ") || "-";
}

function getApplicationInns(application) {
  const directInns = uniqueItems([
    application?.participantInn,
    application?.inn,
    ...(application?.clientInns || [])
  ].filter(Boolean));
  if (directInns.length) return directInns.slice(0, 1);
  const fallback = getApplicationDealRows(application).find((row) => row.inn)?.inn
    || getApplicationContracts(application).find((contract) => contract.inn)?.inn;
  return fallback ? [fallback] : [];
}

function getApplicationInn(application) {
  return getApplicationInns(application).join(", ") || "-";
}

function getApplicationInitiator(application) {
  return application?.initiator || "Система";
}

function getApplicationInitiatorSegment(application) {
  if (application?.initiatorSegment) return application.initiatorSegment;
  if (/система/i.test(getApplicationInitiator(application))) return "Автоматическое создание";
  const product = getApplicationProductSummary(application).toLowerCase();
  if (/ипотеч|рознич/i.test(product)) return "Розничный бизнес";
  if (/гарант|экспорт|корпоратив/i.test(product)) return "Корпоративный бизнес";
  return "МСБ";
}

function getApplicationContractNumber(application) {
  return getApplicationContracts(application).map((contract) => contract.number).join(", ") || application?.contractNumber || "-";
}

function getContractsByNumberList(value) {
  return parseListValue(value)
    .map(getContractByNumber)
    .filter(Boolean);
}

function getApplicationProducts(application) {
  const contractProducts = getApplicationContracts(application).map((contract) => contract.product);
  return uniqueItems([
    ...getApplicationDealRows(application).map((row) => row.product),
    ...(application?.products || []),
    application?.product,
    ...contractProducts
  ].filter(Boolean));
}

function getApplicationProductSummary(application) {
  return getApplicationProducts(application).join(", ") || "-";
}

function getApplicationCurrencyTotals(application) {
  const contracts = getApplicationContracts(application);
  const dealRows = getApplicationDealRows(application).filter((row) => parseNumericInput(row.limit));
  const rows = dealRows.length
    ? dealRows.map((row) => ({ amount: parseNumericInput(row.limit), currency: row.currency || "RUB" }))
    : contracts.length > 1
    ? contracts.map((contract) => ({ amount: parseNumericInput(contract.limit), currency: contract.currency || "RUB" }))
    : [{ amount: parseNumericInput(application?.limit ?? contracts[0]?.limit ?? 0), currency: application?.currency || contracts[0]?.currency || "RUB" }];
  const grouped = rows.reduce((acc, row) => {
    if (!row.amount) return acc;
    acc[row.currency] = (acc[row.currency] || 0) + row.amount;
    return acc;
  }, {});
  return Object.entries(grouped).map(([currency, amount]) => ({ currency, amount }));
}

function getApplicationLimitSummary(application) {
  const totals = getApplicationCurrencyTotals(application);
  if (!totals.length) return "-";
  return totals.map((item) => formatMoney(item.amount, item.currency)).join("; ");
}

function getApplicationCurrencySummary(application) {
  const currencies = uniqueItems([
    ...getApplicationDealRows(application).map((row) => row.currency),
    application?.currency,
    ...getApplicationContracts(application).map((contract) => contract.currency)
  ].filter(Boolean));
  return currencies.join(", ") || "-";
}

function getTaskApplication(task) {
  return getApplication(task?.applicationId || task?.applicationNumber);
}

function getTaskApplicationNumber(task) {
  const application = getTaskApplication(task);
  return application?.number || task?.applicationNumber || "";
}

function getCollateralRegistrationScenario(collateral) {
  const type = String(collateral?.type || "");
  return /недвиж/i.test(type) ? REGISTRATION_SCENARIO_REAL_ESTATE_VISIT : REGISTRATION_SCENARIO_MOVABLE;
}

function getRegistrationScenarioSummary(collaterals = []) {
  const scenarios = uniqueItems(collaterals.map(getCollateralRegistrationScenario).filter(Boolean));
  return {
    scenarios,
    scenario: scenarios[0] || "",
    mixed: scenarios.length > 1
  };
}

function getTaskRegistrationScenario(task, collaterals = getTaskCollaterals(task)) {
  return task?.registrationScenario || getRegistrationScenarioSummary(collaterals).scenario || REGISTRATION_SCENARIO_MOVABLE;
}

function renderRegistrationScenarioOptions(value) {
  return REGISTRATION_SCENARIOS
    .map((item) => `<option value="${escapeHtml(item)}" ${item === value ? "selected" : ""}>${escapeHtml(item)}</option>`)
    .join("");
}

function getTaskParticipantName(task, contracts = getTaskContracts(task), collaterals = getTaskCollaterals(task)) {
  const application = getTaskApplication(task);
  return task?.participantName
    || application?.participantName
    || contracts[0]?.clientName
    || collaterals[0]?.clientName
    || task?.client
    || "";
}

function getTaskParticipantInn(task, contracts = getTaskContracts(task), collaterals = getTaskCollaterals(task)) {
  const application = getTaskApplication(task);
  return task?.dealClientInn
    || task?.participantInn
    || application?.participantInn
    || contracts[0]?.inn
    || collaterals[0]?.clientId
    || "";
}

function generateApplicationId() {
  const max = (state.data.applications || []).reduce((result, item) => {
    const number = Number(String(item.id || "").match(/(\d+)$/)?.[1] || 0);
    return Math.max(result, number);
  }, 420);
  let next = max + 1;
  let id = `APP-2026-${String(next).padStart(4, "0")}`;
  while ((state.data.applications || []).some((item) => item.id === id)) {
    next += 1;
    id = `APP-2026-${String(next).padStart(4, "0")}`;
  }
  return id;
}

function ensureTaskApplication(payload, taskId, contract, collaterals) {
  const number = String(payload.applicationNumber || "").trim();
  if (!number) return null;
  const existing = getApplicationByNumber(number);
  const clientName = existing?.clientName || existing?.participantName || payload.dealClientName || payload.clientName || contract?.clientName || collaterals[0]?.clientName || "";
  const clientInn = existing?.participantInn || existing?.inn || payload.dealClientInn || payload.participantInn || contract?.inn || collaterals[0]?.clientId || "";
  const product = payload.dealProduct || payload.product || contract?.product || "";
  const limit = parseNumericInput(payload.dealLimit ?? payload.limit ?? contract?.limit ?? 0);
  const currency = payload.dealCurrency || payload.currency || contract?.currency || "RUB";
  const contractNumber = payload.contractNumber || contract?.number || "";
  const deal = normalizeApplicationDealRow({
    clientName,
    inn: clientInn,
    contractId: contract?.id || "",
    contractNumber,
    product,
    limit,
    currency,
    collateralIds: collaterals.map((item) => item.id)
  });
  if (existing) {
    existing.createdAt = existing.createdAt || formatTaskHistoryDate(new Date());
    existing.applicationType = existing.applicationType || getApplicationTypeForTaskType(payload.type);
    existing.applicationSubtype = existing.applicationSubtype || getApplicationSubtypeForTaskType(payload.type);
    existing.applicationPurpose = existing.applicationPurpose || getDefaultApplicationPurpose(existing.applicationType, existing.applicationSubtype);
    existing.initiator = existing.initiator || getRole().user;
    existing.contractId = existing.contractId || contract?.id || "";
    existing.contractNumber = existing.contractNumber || contractNumber;
    existing.contractIds = [...new Set([...(existing.contractIds || []), contract?.id].filter(Boolean))];
    existing.clientName = existing.clientName || clientName;
    existing.clientNames = existing.clientName ? [existing.clientName] : [];
    existing.participantName = existing.participantName || payload.participantName || clientName;
    existing.participantInn = existing.participantInn || clientInn;
    existing.clientInns = existing.participantInn ? [existing.participantInn] : [];
    existing.product = existing.product || product;
    existing.limit = existing.limit || limit || 0;
    existing.currency = existing.currency || currency;
    existing.initiatorSegment = existing.initiatorSegment || getApplicationInitiatorSegment(existing);
    existing.collateralIds = [...new Set([...(existing.collateralIds || []), ...collaterals.map((item) => item.id)])];
    existing.taskIds = [...new Set([...(existing.taskIds || []), taskId])];
    existing.deals = Array.isArray(existing.deals) ? existing.deals : [];
    const hasDeal = existing.deals.some((row) =>
      String(row.contractNumber || "") === String(deal.contractNumber || "")
      && String(row.product || "") === String(deal.product || "")
    );
    if (!hasDeal && (deal.clientName || deal.product || deal.contractNumber)) existing.deals.push(deal);
    return existing;
  }
  const applicationType = getApplicationTypeForTaskType(payload.type);
  const applicationSubtype = getApplicationSubtypeForTaskType(payload.type);
  const application = {
    id: generateApplicationId(),
    number,
    createdAt: formatTaskHistoryDate(new Date()),
    source: payload.applicationSource || "Ручное создание",
    applicationType,
    applicationSubtype,
    applicationPurpose: getDefaultApplicationPurpose(applicationType, applicationSubtype),
    initiator: getRole().user,
    initiatorSegment: getApplicationInitiatorSegment({ initiator: getRole().user, product }),
    clientName: clientName || "Клиент не указан",
    clientNames: clientName ? [clientName] : [],
    participantName: payload.participantName || clientName || "Клиент не указан",
    participantInn: clientInn,
    clientInns: clientInn ? [clientInn] : [],
    product,
    limit,
    currency,
    status: "В работе",
    decisionStatus: "Решение по сделке не принято",
    contractId: contract?.id || "",
    contractIds: [contract?.id].filter(Boolean),
    contractNumber,
    collateralIds: collaterals.map((item) => item.id),
    taskIds: [taskId],
    deals: [deal]
  };
  state.data.applications = [...(state.data.applications || []), application];
  return application;
}

function getTaskCollaterals(task) {
  const ids = getTaskCollateralIds(task);
  return ids.map(getCollateral).filter(Boolean);
}

function getTaskCollateralIds(task) {
  return task?.collateralIds?.length ? task.collateralIds : [task?.collateralId].filter(Boolean);
}

function getTaskActiveCollateral(task, collaterals) {
  const activeId = state.taskActiveCollateral[task.id] || task.collateralId || collaterals[0]?.id;
  return collaterals.find((item) => item.id === activeId) || collaterals[0] || null;
}

function uniqueItems(items) {
  return [...new Set(items.filter(Boolean))];
}

function parseListValue(value) {
  return uniqueItems(String(value || "")
    .split(/[,\n;]+/)
    .map((item) => item.trim())
    .filter(Boolean));
}

function getApplicationTypeConfig(type) {
  return APPLICATION_TYPES.find((item) => item.value === type) || APPLICATION_TYPES[0];
}

function getApplicationSubtypeOptions(type) {
  return getApplicationTypeConfig(type).subtypes;
}

function getDefaultApplicationSubtype(type) {
  return getApplicationSubtypeOptions(type)[0] || "";
}

function getDefaultApplicationPurpose(type, subtype = "") {
  const normalizedType = normalizeApplicationType(type);
  const value = String(subtype || "").toLowerCase();
  if (/послед|новый кредит/.test(value)) return "Последующий залог / изменение обеспечения";
  if (/переоцен/.test(value)) return "Переоценка действующего обеспечения";
  if (/мониторинг/.test(value) || normalizedType === "Мониторинг залога") return "Мониторинг обеспечения";
  if (/регистрац|снятие/.test(value) || normalizedType === "Регистрация залога") return "Регистрация / учет залога";
  if (/осмотр|птс|дефект/.test(value) || normalizedType === "Осмотр имущества") return "Проверка предмета залога";
  if (/служеб|иное|егрн|цб/.test(value) || normalizedType === "Служебная записка" || normalizedType === "Иное") return "Служебное обращение";
  return "Новый кредит / новая сделка";
}

function getApplicationDocumentTaskType(type, subtype = "") {
  const normalizedType = normalizeApplicationType(type);
  const value = String(subtype || "").toLowerCase();
  if (normalizedType === "Регистрация залога") return TASK_TYPE_REGISTRATION;
  if (normalizedType === "Мониторинг залога") return /внеплан/i.test(value) ? "Внеплановый мониторинг" : "Плановый мониторинг";
  if (normalizedType === "Осмотр имущества") {
    if (/дефект/i.test(value)) return TASK_TYPE_DEFECT_INSPECTION;
    return /повтор/i.test(value) ? "Повторный осмотр" : "Первичный осмотр";
  }
  if (normalizedType === "Оценка залога") return /списоч|массов/i.test(value) ? "Списочная переоценка" : "Единичная переоценка";
  return "Заявка";
}

function getApplicationInitialTaskType(type, subtype = "") {
  const taskType = getApplicationDocumentTaskType(type, subtype);
  return taskTypes.includes(taskType) ? getUnifiedTaskType(taskType) : "Первичный осмотр";
}

function getApplicationInitialInspectionFormat(type, subtype = "") {
  const normalizedType = normalizeApplicationType(type);
  const value = String(subtype || "").toLowerCase();
  if (normalizedType !== "Осмотр имущества") return "";
  if (/документ/i.test(value)) return "Документарный осмотр";
  return "Физический осмотр";
}

function getDefaultTaskAssigneeForType(type) {
  const value = String(type || "").toLowerCase();
  if (/регистрац/.test(value)) return "Елена Морозова";
  if (/оцен|переоцен/.test(value)) return "Алексей Соколов";
  if (/осмотр|мониторинг|дефект/.test(value)) return "Сергей Иванов";
  return employees[0];
}

function getDefaultInitialTaskDueDate(createdAt = "") {
  const match = String(createdAt || "").match(/^(\d{4})-(\d{2})-(\d{2})/);
  const date = match
    ? new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]))
    : new Date();
  date.setDate(date.getDate() + 3);
  const pad = (value) => String(value).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function normalizeApplicationType(type) {
  return getApplicationTypeConfig(type || APPLICATION_TYPES[0].value).value;
}

function normalizeApplicationSubtype(type, subtype) {
  const options = getApplicationSubtypeOptions(type);
  return options.includes(subtype) ? subtype : options[0] || "";
}

function normalizeApplicationPurpose(type, subtype, purpose) {
  const options = APPLICATION_PURPOSES;
  return options.includes(purpose) ? purpose : getDefaultApplicationPurpose(type, subtype);
}

function getApplicationType(application) {
  if (application?.applicationType) return normalizeApplicationType(application.applicationType);
  const taskTypesForApplication = getApplicationTasks(application).map((task) => task.type).join(" ");
  if (/постанов|регистрац/i.test(taskTypesForApplication)) return "Регистрация залога";
  if (/мониторинг/i.test(taskTypesForApplication)) return "Мониторинг залога";
  if (/осмотр/i.test(taskTypesForApplication)) return "Осмотр имущества";
  return "Оценка залога";
}

function getApplicationSubtype(application) {
  const type = getApplicationType(application);
  if (application?.applicationSubtype) return normalizeApplicationSubtype(type, application.applicationSubtype);
  const taskTypesForApplication = getApplicationTasks(application).map((task) => task.type).join(" ");
  if (/списочн|переоцен/i.test(taskTypesForApplication)) return normalizeApplicationSubtype(type, "Переоценка");
  if (/первич/i.test(taskTypesForApplication)) return normalizeApplicationSubtype(type, "Первоначальный осмотр");
  if (/постанов|регистрац/i.test(taskTypesForApplication)) return normalizeApplicationSubtype(type, REGISTRATION_SCENARIO_MOVABLE);
  return getDefaultApplicationSubtype(type);
}

function getApplicationPurpose(application) {
  const type = getApplicationType(application);
  const subtype = getApplicationSubtype(application);
  return normalizeApplicationPurpose(type, subtype, application?.applicationPurpose);
}

function getApplicationTypeForTaskType(taskType) {
  const value = String(taskType || "");
  if (/постанов|регистрац/i.test(value)) return "Регистрация залога";
  if (/мониторинг/i.test(value)) return "Мониторинг залога";
  if (/осмотр|дефект/i.test(value)) return "Осмотр имущества";
  return "Оценка залога";
}

function getApplicationSubtypeForTaskType(taskType) {
  const type = getApplicationTypeForTaskType(taskType);
  const value = String(taskType || "");
  if (/дефект/i.test(value)) return normalizeApplicationSubtype(type, "Контроль дефектовки");
  if (/первич.*осмотр/i.test(value)) return normalizeApplicationSubtype(type, "Первоначальный осмотр");
  if (/повтор.*осмотр/i.test(value)) return normalizeApplicationSubtype(type, "Повторный осмотр");
  if (/план.*мониторинг/i.test(value)) return normalizeApplicationSubtype(type, "Плановый мониторинг");
  if (/внеплан.*мониторинг/i.test(value)) return normalizeApplicationSubtype(type, "Внеплановый мониторинг");
  if (/переоцен/i.test(value)) return normalizeApplicationSubtype(type, "Переоценка");
  if (/постанов|регистрац/i.test(value)) return normalizeApplicationSubtype(type, REGISTRATION_SCENARIO_MOVABLE);
  return getDefaultApplicationSubtype(type);
}

function normalizeApplicationDealRow(row = {}, index = 0) {
  const contract = getContract(row.contractId) || getContractByNumber(row.contractNumber);
  const limit = parseNumericInput(row.limit ?? row.amount ?? contract?.limit ?? 0);
  return {
    id: row.id || `deal-${index + 1}`,
    clientName: row.clientName || row.name || contract?.clientName || "",
    inn: row.inn || row.clientInn || contract?.inn || "",
    contractId: row.contractId || contract?.id || "",
    contractNumber: row.contractNumber || contract?.number || "",
    product: row.product || contract?.product || "",
    limit: limit || "",
    currency: row.currency || contract?.currency || "RUB",
    collateralIds: uniqueItems([...(row.collateralIds || []), ...parseListValue(row.collateralId)].filter(Boolean)),
    comment: row.comment || ""
  };
}

function getApplicationDealRows(application) {
  if (!application) return [];
  if (Array.isArray(application.deals) && application.deals.length) {
    const clientName = application.clientName || application.participantName || "";
    const inn = application.participantInn || application.inn || "";
    return application.deals.map((row, index) => normalizeApplicationDealRow({
      ...row,
      clientName: clientName || row.clientName,
      inn: inn || row.inn
    }, index));
  }
  const contractIds = new Set([...(application.contractIds || []), application.contractId].filter(Boolean));
  parseListValue(application.contractNumber).forEach((number) => {
    const contract = getContractByNumber(number);
    if (contract) contractIds.add(contract.id);
  });
  const contracts = [...contractIds].map(getContract).filter(Boolean);
  if (contracts.length) {
    return contracts.map((contract, index) => {
      const collateralIds = (application.collateralIds || [])
        .filter((id) => getCollateral(id)?.contractIds?.includes(contract.id));
      return normalizeApplicationDealRow({
        id: `deal-${index + 1}`,
        clientName: contract.clientName,
        inn: contract.inn,
        contractId: contract.id,
        contractNumber: contract.number,
        product: contract.product,
        limit: contract.limit,
        currency: contract.currency,
        collateralIds: collateralIds.length || contracts.length > 1 ? collateralIds : application.collateralIds || []
      }, index);
    });
  }
  const hasLegacyDeal = application.clientName || application.participantName || application.participantInn || application.product || application.limit;
  if (!hasLegacyDeal) return [];
  return [normalizeApplicationDealRow({
    id: "deal-1",
    clientName: application.clientName || application.participantName,
    inn: application.participantInn || application.inn,
    contractNumber: application.contractNumber,
    product: application.product,
    limit: application.limit,
    currency: application.currency,
    collateralIds: application.collateralIds || []
  })];
}

function getApplicationDealText(row) {
  const amount = parseNumericInput(row.limit) ? formatMoney(row.limit, row.currency || "RUB") : "сумма не указана";
  const contract = row.contractNumber || "договор не указан";
  const collateralCount = (row.collateralIds || []).length;
  const collaterals = collateralCount ? `, ${collateralCount} ${pluralize(collateralCount, "залог", "залога", "залогов")}` : "";
  return `${contract} - ${row.product || "продукт не указан"} - ${amount}${collaterals}`;
}

function renderApplicationDealsSummary(application) {
  const rows = getApplicationDealRows(application);
  if (!rows.length) return `<span class="muted">Не заполнено</span>`;
  return `<div class="application-deals-summary">${rows.map((row) => `<div>${escapeHtml(getApplicationDealText(row))}</div>`).join("")}</div>`;
}

function isInternalTaskParty(value) {
  return /управление залогов|залоговое подразделение|планировщик|система/i.test(String(value || ""));
}

function getTaskContracts(task, collaterals = getTaskCollaterals(task)) {
  const ids = [];
  collaterals.forEach((collateral) => ids.push(...(collateral.contractIds || [])));
  const application = getTaskApplication(task);
  if (application?.contractId) ids.push(application.contractId);
  if (application?.contractIds?.length) ids.push(...application.contractIds);
  if (application) {
    getApplicationDealRows(application).forEach((row) => {
      if (row.contractId) ids.push(row.contractId);
      const contract = getContractByNumber(row.contractNumber);
      if (contract) ids.push(contract.id);
    });
    parseListValue(application.contractNumber).forEach((number) => {
      const contract = getContractByNumber(number);
      if (contract) ids.push(contract.id);
    });
  }
  if (!ids.length && task?.contractId) ids.push(task.contractId);
  parseListValue(task?.contractNumber).forEach((number) => {
    const contract = getContractByNumber(number);
    if (contract) ids.push(contract.id);
  });
  return uniqueItems(ids).map(getContract).filter(Boolean);
}

function getTaskActiveContracts(task, activeCollateral) {
  const application = getTaskApplication(task);
  const ids = activeCollateral?.contractIds?.length ? activeCollateral.contractIds : [application?.contractId, task?.contractId].filter(Boolean);
  return uniqueItems(ids).map(getContract).filter(Boolean);
}

function getTaskActiveContract(task, activeCollateral) {
  return getTaskActiveContracts(task, activeCollateral)[0] || getContract(task?.contractId);
}

function getTaskContractClientNames(task, collaterals = getTaskCollaterals(task)) {
  const application = getTaskApplication(task);
  const applicationClient = getApplicationClientName(application);
  if (applicationClient && applicationClient !== "-") return [applicationClient];
  const names = getTaskContracts(task, collaterals).map((contract) => contract.clientName);
  if (!names.length && task?.client && !isInternalTaskParty(task.client)) names.push(task.client);
  return uniqueItems(names);
}

function getContractPartyRole(contract) {
  const role = contract?.participants?.find((item) => !/залогодатель|поручитель/i.test(item.role || ""))?.role;
  if (role) return role;
  const product = String(contract?.product || "").toLowerCase();
  if (product.includes("гарант")) return "Принципал";
  if (product.includes("лизинг")) return "Лизингополучатель";
  if (product.includes("кредит") || product.includes("ипотеч")) return "Заемщик";
  return "Клиент по договору";
}

function summarizeNames(names, limit = 2) {
  const unique = uniqueItems(names);
  if (!unique.length) return "-";
  if (unique.length <= limit) return unique.join(", ");
  return `${unique.length} клиента по договору: ${unique.slice(0, limit).join(", ")} +${unique.length - limit}`;
}

function getTaskClientSummary(task, collaterals = getTaskCollaterals(task)) {
  return summarizeNames(getTaskContractClientNames(task, collaterals));
}

function renderTaskRegistryApplicationCell(task) {
  const application = getTaskApplication(task);
  const number = application?.number || task?.applicationNumber;
  if (!number) return `<span class="muted">-</span>`;
  if (!application || !hasPermission(getRole(), "appRegView")) return `<span>${escapeHtml(number)}</span>`;
  return `<button class="link registry-object-link" data-route="${getApplicationCardRoute(application)}">${escapeHtml(number)}</button>`;
}

function renderApplicationTasksLink(number) {
  if (!number) return `<span class="muted">-</span>`;
  const direction = getAvailableTaskDirections(getRole())[0];
  if (!direction) return `<span>${escapeHtml(number)}</span>`;
  const route = getTaskDirectionConfig(direction).path;
  return `<button class="link registry-object-link" data-route="${route}?applicationNumber=${encodeURIComponent(number)}">${escapeHtml(number)}</button>`;
}

function renderTaskRegistryContractCell(task, contracts) {
  const rows = contracts?.length ? contracts : [getContract(task?.contractId)].filter(Boolean);
  return renderContractNumberList(rows, task?.contractNumber);
}

function renderContractNumberList(contracts = [], fallback = "") {
  const numbers = uniqueItems([
    ...(contracts || []).map((contract) => contract?.number),
    ...parseListValue(fallback)
  ].filter(Boolean));
  if (!numbers.length) return `<span class="muted">-</span>`;
  return `<span class="contract-number-list">${numbers.map(escapeHtml).join(",<br>")}</span>`;
}

function renderTaskRegistryCollateralCell(task, collaterals) {
  const rows = collaterals?.length ? collaterals : [getCollateral(task?.collateralId)].filter(Boolean);
  if (!rows.length) return `<span class="muted">-</span>`;
  const values = rows.map((collateral) => {
    const identifier = getCollateralObjectIdentifier(collateral);
    if (!hasPermission(getRole(), "collateralView")) return escapeHtml(identifier);
    return `<a class="link registry-object-link" href="#${escapeHtml(getCollateralCardRoute(collateral.id, { task }))}">${escapeHtml(identifier)}</a>`;
  });
  return `<span class="registry-object-list">${values.join(",<br>")}</span>`;
}

function getCollateralCardRoute(collateralId, context = {}) {
  const route = `/app/collaterals/${encodeURIComponent(collateralId || "")}`;
  const params = new URLSearchParams();
  const task = context.task || (context.taskId ? getTask(context.taskId) : null);
  const application = context.application || (context.applicationId ? getApplicationByIdOrNumber(context.applicationId) : null);
  if (task?.id && task.id !== "new-task-draft") params.set("task", task.id);
  else if (application) params.set("application", application.id || application.number);
  if (context.tab) params.set("tab", context.tab);
  const query = params.toString();
  return query ? `${route}?${query}` : route;
}

function getTaskCollateralCardRoute(task, collateralId, options = {}) {
  const application = options.sourceApplication || null;
  if (application) return getCollateralCardRoute(collateralId, { application });
  if (task?.id && task.id !== "new-task-draft" && getTask(task.id)) return getCollateralCardRoute(collateralId, { task });
  return getCollateralCardRoute(collateralId);
}

function renderTaskRegistryPledgorCell(collaterals) {
  const pledgors = uniqueItems((collaterals || []).map((item) => getMainPledgor(item).name));
  if (!pledgors.length) return `<span class="muted">-</span>`;
  return `<span class="registry-object-list">${pledgors.map(escapeHtml).join(",<br>")}</span>`;
}

function summarizePledgors(names, limit = 1) {
  const unique = uniqueItems(names);
  if (!unique.length) return "-";
  if (unique.length <= limit) return unique.join(", ");
  return `${unique.length} ${pluralize(unique.length, "залогодатель", "залогодателя", "залогодателей")}: ${unique.slice(0, limit).join(", ")} +${unique.length - limit}`;
}

function getTaskCreatedDateTime(task) {
  const createdEvent = (task?.history || [])
    .find((event) => /создан/i.test(String(event.action || "")) && event.date);
  return createdEvent?.date || task?.createdAt || "-";
}

function getTaskInitiator(task) {
  if (!task) return "-";
  if (task.autoInitiated === true || isTaskCreatedAutomatically(task)) return "Система";

  const creationUser = (task.history || [])
    .filter((event) => /создан/i.test(String(event.action || "")))
    .map((event) => event.user)
    .find((user) => employees.includes(user));
  const employeeUser = creationUser
    || (task.history || []).map((event) => event.user).find((user) => employees.includes(user))
    || (employees.includes(task.assignee) ? task.assignee : "");

  return employeeUser || "-";
}

function getTaskApplicationInitiator(task) {
  const application = getTaskApplication(task);
  return application?.initiator || task?.initiator || getTaskInitiator(task) || "-";
}

function isTaskCreatedAutomatically(task) {
  const source = String(task?.source || "");
  const creationUser = (task?.history || [])
    .filter((event) => /создан/i.test(String(event.action || "")))
    .map((event) => String(event.user || ""))
    .find(Boolean);
  const creationText = `${source} ${creationUser}`.toLowerCase();
  return /система|абс|конвейер|триггер|расписание|планировщик|регламент|email|почтовый сервер|маркетплейс|авто\.ру|авито|циан/.test(creationText);
}

function normalizeTaskType(type) {
  return String(type || "").toLowerCase();
}

function isInspectionTaskType(type) {
  const normalized = normalizeTaskType(type);
  return normalized.includes("осмотр") && !isMobileInspectionTaskType(type);
}

function isInspectionCardTaskType(type) {
  return isInspectionTaskType(type) || isMonitoringTaskType(type);
}

function isDefectInspectionTaskType(type) {
  return normalizeTaskType(type).includes("дефект");
}

function isMobileInspectionTaskType(type) {
  const normalized = normalizeTaskType(type);
  return normalized.includes("выездной осмотр");
}

function getInspectionFormat(task) {
  if (task?.inspectionFormat) return task.inspectionFormat;
  if (isMonitoringTaskType(task?.type)) {
    const context = `${task?.title || ""} ${task?.result || ""} ${task?.source || ""}`.toLowerCase();
    if (/документ|страхован|полис|платеж|преми|рын|егрн|циан|реестр/.test(context)) return "Документарный осмотр";
    return "Физический осмотр";
  }
  const applicationSubtype = getTaskApplicationSubtypeValue(task);
  return /документар/i.test(applicationSubtype) ? "Документарный осмотр" : "Физический осмотр";
}

function isDocumentaryInspectionTask(task) {
  return /документар/i.test(getInspectionFormat(task));
}

function isMonitoringTaskType(type) {
  return normalizeTaskType(type).includes("мониторинг");
}

function isRevaluationTaskType(type) {
  return normalizeTaskType(type).includes("переоценк");
}

function isListRevaluationTaskType(type) {
  return normalizeTaskType(type).includes("списоч");
}

function isRegistrationTaskType(type) {
  return getUnifiedTaskType(type) === TASK_TYPE_REGISTRATION;
}

function isPledgeOperationTaskType(type) {
  const normalized = normalizeTaskType(getUnifiedTaskType(type));
  return isRegistrationTaskType(type) || normalized.includes("снятие обременения") || normalized.includes("замена залога");
}

function isReportingTaskType(type) {
  return normalizeTaskType(type).includes("отчетност");
}

function render() {
  const role = getRole();
  const { path, query } = parseRoute();
  const isMobileOnlyRole = role.menu.length === 1 && role.menu.includes("mobileEmployee");
  if (isMobileOnlyRole && !path.startsWith("/mobile/employee/tasks")) {
    window.location.hash = "/mobile/employee/tasks";
    return;
  }
  const content = renderRoute(path, query);
  if (isMobileOnlyRole) {
    app.innerHTML = `
      <div class="mobile-app-shell">
        <div class="mobile-prototype-toolbar">
          ${renderRoleSwitcher(role)}
        </div>
        <main class="mobile-main">${content}</main>
        ${renderModal()}
        ${renderToasts()}
      </div>
    `;
    restorePendingScrollPosition();
    restorePendingMobileScrollPosition();
    restorePendingFilterFocus();
    focusPendingRegistryTable();
    return;
  }
  app.innerHTML = `
    <div class="app-shell">
      ${renderTopbar(role, path)}
      <main class="main">${content}</main>
      ${renderModal()}
      ${renderToasts()}
    </div>
  `;
  restorePendingScrollPosition();
  restorePendingFilterFocus();
  focusPendingRegistryTable();
}

function renderTopbar(role, path) {
  const menu = getAvailableNavItems(role);
  const mobileMenu = navItems.filter((item) => role.menu.includes(item.id) && item.id === "mobileEmployee");
  const items = menu.length ? menu : mobileMenu;
  const defaultRoute = getDefaultRouteForRole(role);
  const activeTask = path.startsWith("/app/tasks/") && !getTaskDirectionFromPath(path) ? getTask(path.split("/").pop()) : null;
  const activeTaskPath = activeTask ? getTaskDirectionConfig(getTaskDirection(activeTask)).path : "";
  const activeItem = items.find((item) => path === item.path || path.startsWith(`${item.path}/`) || item.path === activeTaskPath) || items[0];
  return `
    <aside class="arm-sidebar">
      <div class="sidebar-brand-wrap">
        <button class="brand brand-visual-logo" data-route="${defaultRoute}" aria-label="Главная страница системы">
          <svg class="system-logo system-logo-inline" viewBox="0 0 178 44" aria-hidden="true" focusable="false">
            <path class="logo-track" d="M10 29H40L61 18H74M104 18H118L139 29H168" />
            <g class="logo-object logo-home">
              <path d="M31 14L18 24V35H44V24L31 14Z" />
              <path d="M26 35V27H36V35" />
            </g>
            <g class="logo-object logo-car">
              <path d="M112 27H136L141 33H146C148 33 150 35 150 37V39H107V37C107 35 109 33 111 33H115L119 29" />
              <circle cx="118" cy="39" r="3" />
              <circle cx="137" cy="39" r="3" />
            </g>
            <g class="logo-object logo-doc">
              <path d="M153 13H168V31H153Z" />
              <path d="M157 19H164M157 24H164" />
            </g>
            <g class="logo-shield">
              <path d="M89 6L105 12V23C105 32 99 37 89 40C79 37 73 32 73 23V12L89 6Z" />
              <path d="M82 23L87 28L97 17" />
            </g>
            <g class="logo-dots">
              <circle cx="40" cy="29" r="3" />
              <circle cx="61" cy="18" r="3" />
              <circle cx="118" cy="18" r="3" />
              <circle cx="139" cy="29" r="3" />
            </g>
            <path class="logo-baseline" d="M12 41H166" />
          </svg>
        </button>
      </div>
      <nav class="top-nav" aria-label="Основные разделы">
        ${renderSidebarNavItems(items, path, activeTaskPath)}
      </nav>
      <div class="sidebar-signal" aria-hidden="true">
        <span></span><span></span><span></span>
      </div>
    </aside>
    <header class="app-header">
      <div class="workspace-heading">
        <span>АРМ</span>
        <strong>${escapeHtml(activeItem?.label || "Рабочая область")}</strong>
      </div>
      ${renderRoleSwitcher(role)}
    </header>
  `;
}

function renderSidebarNavItems(items, path, activeTaskPath) {
  let currentGroup = "";
  return items.map((item) => {
    const groupLabel = item.group && item.group !== currentGroup
      ? `<span class="nav-group-label">${escapeHtml(item.group)}</span>`
      : "";
    if (item.group) currentGroup = item.group;
    const active = path === item.path || path.startsWith(`${item.path}/`) || item.path === activeTaskPath;
    return `
      ${groupLabel}
      <button class="${active ? "active" : ""}" data-route="${item.path}">
        <span class="nav-icon" aria-hidden="true">${renderNavIcon(item.id)}</span>
        <span class="nav-label">${escapeHtml(item.label)}</span>
      </button>
    `;
  }).join("");
}

function renderNavIcon(id) {
  const icons = {
    tasks: `<svg viewBox="0 0 24 24" focusable="false"><path d="M9 6h11M9 12h11M9 18h11"/><path d="m4 6 1.2 1.2L7.5 5M4 12l1.2 1.2L7.5 11M4 18l1.2 1.2L7.5 17"/></svg>`,
    tasksEvaluation: `<svg viewBox="0 0 24 24" focusable="false"><path d="M4 19h16"/><path d="M7 16l3-7 3 4 4-8"/><circle cx="17" cy="5" r="2"/></svg>`,
    tasksInspection: `<svg viewBox="0 0 24 24" focusable="false"><path d="M3 11s3.5-6 9-6 9 6 9 6-3.5 6-9 6-9-6-9-6Z"/><circle cx="12" cy="11" r="3"/><path d="M6 20h12"/></svg>`,
    tasksRegistration: `<svg viewBox="0 0 24 24" focusable="false"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 13h6M10 17h3"/><path d="m15 18 2 2 4-5"/></svg>`,
    applications: `<svg viewBox="0 0 24 24" focusable="false"><path d="M6 3h9l3 3v15H6z"/><path d="M15 3v4h4M9 11h6M9 15h6M9 19h4"/><path d="M4 7H2v14h10"/></svg>`,
    contracts: `<svg viewBox="0 0 24 24" focusable="false"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h6M10 16h6M10 20h4"/><path d="M5 7H3v14h10"/></svg>`,
    collaterals: `<svg viewBox="0 0 24 24" focusable="false"><path d="M4 10.5 12 4l8 6.5"/><path d="M6 9.5V20h12V9.5"/><path d="M9 20v-6h6v6"/><path d="M4 20h16"/></svg>`
  };
  return icons[id] || `<svg viewBox="0 0 24 24" focusable="false"><path d="M5 12h14M12 5v14"/></svg>`;
}

function renderRoute(path, query) {
  const role = getRole();
  const defaultRoute = getDefaultRouteForRole(role);
  if (path === "/" || path === "/app" || path === "/app/tasks") {
    const direction = getAvailableTaskDirections(role)[0];
    if (direction) return renderTasksRegistry(query, direction);
    return renderRoute(defaultRoute, query);
  }
  const direction = getTaskDirectionFromPath(path);
  if (direction) {
    if (!canViewTaskDirection(direction, role)) return renderNotFound("Раздел недоступен", defaultRoute);
    return renderTasksRegistry(query, direction);
  }
  if (path === "/app/tasks/new") return renderNotFound("Раздел недоступен", defaultRoute);
  if (path.startsWith("/app/tasks/")) {
    const task = getTask(path.split("/").pop());
    if (!task) return renderNotFound("Задача не найдена", defaultRoute);
    if (!canViewTask(task, role)) return renderNotFound("Задача недоступна для выбранной роли", defaultRoute);
    return renderTaskCard(task.id);
  }
  if (path === "/app/applications/new") return hasPermission(role, "appCreateEdit") ? renderApplicationCreate(query) : renderNotFound("Раздел недоступен", defaultRoute);
  if (path === "/app/applications") return hasPermission(role, "appRegView") ? renderApplicationsRegistry() : renderNotFound("Раздел недоступен", defaultRoute);
  if (path.startsWith("/app/applications/")) return hasPermission(role, "appRegView") ? renderApplicationCard(decodeURIComponent(path.split("/").pop() || "")) : renderNotFound("Раздел недоступен", defaultRoute);
  if (path === "/app/contracts" || path.startsWith("/app/contracts/")) return renderNotFound("Раздел недоступен", "/app/applications");
  if (path === "/app/collaterals") return hasPermission(role, "collateralView") ? renderCollateralsRegistry(query) : renderNotFound("Раздел недоступен", defaultRoute);
  if (path.startsWith("/app/collaterals/")) return hasPermission(role, "collateralView") ? renderCollateralCard(path.split("/").pop(), query) : renderNotFound("Раздел недоступен", defaultRoute);
  if (path === "/app/insurances" || path === "/app/reports") return renderNotFound("Раздел недоступен", defaultRoute);
  if (path.startsWith("/app/print/")) return renderPrintPreview(path.split("/").pop());
  if (path === "/mobile/employee/tasks" || path.startsWith("/mobile/employee/tasks/")) return renderNotFound("Раздел недоступен", defaultRoute);
  return renderNotFound("Раздел не найден", defaultRoute);
}

function renderPageHeader(title, text, actions = "") {
  const defaultRoute = getDefaultRouteForRole(getRole());
  return `
    <div class="breadcrumbs"><button class="link" data-route="${defaultRoute}">Главная</button><span>/</span><span>${escapeHtml(title)}</span></div>
    <section class="page-header">
      <div><h1>${escapeHtml(title)}</h1>${text ? `<p>${escapeHtml(text)}</p>` : ""}</div>
      <div class="header-actions">${actions}</div>
    </section>
  `;
}

function renderNotFound(title, route) {
  return `<section class="error-state"><h2>${escapeHtml(title)}</h2><button class="btn btn-primary" data-route="${route}">Вернуться</button></section>`;
}

function renderInfoGrid(items) {
  return `
    <dl class="info-grid">
      ${Object.entries(items).map(([key, value]) => `
        <div><dt>${escapeHtml(key)}</dt><dd>${typeof value === "string" && value.startsWith("<") ? value : escapeHtml(value ?? "-")}</dd></div>
      `).join("")}
    </dl>
  `;
}

const chartPalette = ["#2563eb", "#1e40af", "#0ea5e9", "#b45309", "#b91c1c", "#6d28d9", "#15803d"];
const contractCurrencyRates = { RUB: 1 };

function sumBy(items, getter) {
  return items.reduce((sum, item) => sum + Number(getter(item) || 0), 0);
}

function countBy(items, getter) {
  return items.reduce((acc, item) => {
    const key = getter(item) || "Не указано";
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});
}

function toSegments(counter, options = {}) {
  const entries = Array.isArray(counter) ? counter : Object.entries(counter).map(([label, value]) => ({ label, value }));
  return entries
    .filter((item) => Number(item.value) > 0)
    .sort((a, b) => Number(b.value) - Number(a.value))
    .slice(0, options.limit || entries.length)
    .map((item, index) => ({ ...item, color: item.color || chartPalette[index % chartPalette.length] }));
}

function formatShortMoney(value) {
  const amount = Number(value || 0);
  if (amount >= 1_000_000_000) return `${(amount / 1_000_000_000).toFixed(1).replace(".", ",")} млрд ₽`;
  if (amount >= 1_000_000) return `${Math.round(amount / 1_000_000).toLocaleString("ru-RU")} млн ₽`;
  return formatMoney(amount, "RUB");
}

function getContractDebtRub(contract) {
  const rate = contractCurrencyRates[contract?.currency] || 1;
  return Math.round(Number(contract?.debt || 0) * rate);
}

function renderContractDebtCell(contract) {
  const original = contract.currency && contract.currency !== "RUB"
    ? `<br><small>${formatMoney(contract.debt, contract.currency)}</small>`
    : "";
  return `${formatMoney(getContractDebtRub(contract))}${original}`;
}

function getTaskUrgency(task) {
  if (task.sla === "Просрочена") return "Просрочены";
  if (task.sla === "Сегодня") return "Сегодня";
  if (task.sla === "Неделя") return "На неделе";
  return "В срок";
}

const closedTaskStatuses = ["Завершена"];

function isTaskClosed(task) {
  return closedTaskStatuses.includes(task?.status);
}

function isManagerRole(role) {
  return Boolean(role?.permissions?.reassign);
}

function canSendTaskToRevision(role) {
  return Boolean(role?.permissions?.returnTask);
}

function isTaskApprover(role, task) {
  return false;
}

function getApproverOptions(task) {
  return [...new Set([
    task?.approval?.approver,
    roles.find((role) => role.id === "evaluationManager")?.user,
    roles.find((role) => role.id === "inspectionManager")?.user,
    ...employees
  ].filter(Boolean))];
}

function matchesTaskRegistryTab(task, tabId, role = getRole()) {
  if (tabId === "completed") return isTaskClosed(task);
  if (tabId === "all") return !isTaskClosed(task);
  return task.assignee === role.user && !isTaskClosed(task);
}

function renderTaskRegistryTabs(rows, activeTab, role) {
  const tabs = [
    { id: "mine", label: "Мои задачи", hint: "в работе у текущего пользователя" },
    { id: "all", label: "Все задачи", hint: "доступные задачи направления" },
    { id: "completed", label: "Завершенные", hint: "архив" }
  ];
  return `
    <div class="tabs registry-tabs" role="tablist" aria-label="Срез задач">
      ${tabs.map((tab) => {
        const count = rows.filter((task) => matchesTaskRegistryTab(task, tab.id, role)).length;
        return `
          <button type="button" role="tab" class="${activeTab === tab.id ? "active" : ""}" data-action="task-registry-tab" data-tab="${tab.id}">
            <span>${escapeHtml(tab.label)}</span>
            <small>${escapeHtml(tab.hint)}</small>
            <strong>${count}</strong>
          </button>
        `;
      }).join("")}
    </div>
  `;
}

function renderKpiGrid(cards) {
  return `
    <section class="kpi-grid registry-kpi-grid">
      ${cards.map((card) => {
        const tag = card.action ? "button" : "div";
        const type = card.action ? ' type="button"' : "";
        return `
        <${tag}${type} class="kpi-card ${card.tone || ""} ${card.active ? "active" : ""}" ${card.action || ""} aria-label="${escapeHtml(card.label)}">
          <span>${escapeHtml(card.label)}</span>
          <strong>${escapeHtml(card.value)}</strong>
          ${card.hint ? `<small>${escapeHtml(card.hint)}</small>` : ""}
        </${tag}>
      `;
      }).join("")}
    </section>
  `;
}

function hasVisualFilters(scope) {
  return Object.values(state.visualFilters[scope] || {}).some(Boolean);
}

function focusPendingRegistryTable() {
  const scope = state.pendingRegistryFocus;
  if (!scope) return;
  state.pendingRegistryFocus = "";
  const focus = () => {
    const table = document.querySelector(`[data-registry-table="${scope}"]`);
    if (!table) return;
    table.scrollIntoView({ behavior: "smooth", block: "start" });
    table.focus({ preventScroll: true });
  };
  if (typeof window.requestAnimationFrame === "function") window.requestAnimationFrame(focus);
  else setTimeout(focus, 0);
}

function restorePendingScrollPosition() {
  const target = state.pendingScrollRestore;
  if (!target) return;
  state.pendingScrollRestore = null;
  const restore = () => window.scrollTo({ top: target.top, left: target.left, behavior: "instant" });
  if (typeof window.requestAnimationFrame === "function") window.requestAnimationFrame(restore);
  else setTimeout(restore, 0);
}

function rememberMobileScrollPosition(field) {
  const content = field?.closest?.(".mobile-content");
  state.pendingMobileScrollRestore = {
    windowTop: window.scrollY,
    windowLeft: window.scrollX,
    contentTop: content?.scrollTop || 0,
    task: field?.dataset?.task || "",
    collateral: field?.dataset?.collateral || "",
    factor: field?.dataset?.factor || ""
  };
}

function restorePendingMobileScrollPosition() {
  const target = state.pendingMobileScrollRestore;
  if (!target) return;
  state.pendingMobileScrollRestore = null;
  const restore = () => {
    const content = document.querySelector(".mobile-content");
    if (content) content.scrollTop = target.contentTop;
    window.scrollTo({ top: target.windowTop, left: target.windowLeft, behavior: "instant" });
    const field = Array.from(document.querySelectorAll("[data-mobile-check-factor]"))
      .find((item) => item.dataset.task === target.task && item.dataset.collateral === target.collateral && item.dataset.factor === target.factor);
    if (field) field.focus({ preventScroll: true });
  };
  if (typeof window.requestAnimationFrame === "function") window.requestAnimationFrame(restore);
  else setTimeout(restore, 0);
}

function restorePendingFilterFocus() {
  const target = state.pendingFilterFocus;
  if (!target) return;
  state.pendingFilterFocus = null;
  const restore = () => {
    const field = document.querySelector(`[data-filter-scope="${target.scope}"][data-filter-name="${target.name}"]`);
    if (!field) return;
    field.focus({ preventScroll: true });
    if (typeof field.setSelectionRange === "function") {
      field.setSelectionRange(target.selectionStart, target.selectionEnd);
    }
  };
  if (typeof window.requestAnimationFrame === "function") window.requestAnimationFrame(restore);
  else setTimeout(restore, 0);
}

function isTextRegistryFilter(field) {
  return field?.matches?.("input[data-filter-scope]")
    && !["date", "checkbox", "radio", "file"].includes(field.type);
}

function updateRegistryFilter(field) {
  const scope = field.dataset.filterScope;
  const name = field.dataset.filterName;
  if (!state.filters[scope]) return;
  state.filters[scope][name] = field.value;
}

function scheduleRegistryFilterRender(field) {
  if (registryFilterRenderTimer) clearTimeout(registryFilterRenderTimer);
  state.pendingFilterFocus = {
    scope: field.dataset.filterScope,
    name: field.dataset.filterName,
    selectionStart: typeof field.selectionStart === "number" ? field.selectionStart : field.value.length,
    selectionEnd: typeof field.selectionEnd === "number" ? field.selectionEnd : field.value.length
  };
  state.pendingScrollRestore = { top: window.scrollY, left: window.scrollX };
  registryFilterRenderTimer = setTimeout(() => {
    registryFilterRenderTimer = null;
    render();
  }, 350);
}

function resetVisualFilters(scope) {
  if (!state.visualFilters[scope]) return;
  state.visualFilters[scope] = Object.fromEntries(Object.keys(state.visualFilters[scope]).map((key) => [key, ""]));
}

function applyRegistryKpiFilter(scope, filter, value) {
  if (!state.visualFilters[scope]) return;
  const sameActive = filter && filter !== "all" && state.visualFilters[scope]?.[filter] === value;
  resetVisualFilters(scope);
  if (filter && filter !== "all" && !sameActive) state.visualFilters[scope][filter] = value;
  state.pendingRegistryFocus = scope;
}

function renderDonutPanel({ title, subtitle, segments, total, centerLabel, scope, filterKey, activeValue, compact = false }) {
  const numericTotal = Number(total) || segments.reduce((sum, item) => sum + Number(item.value || 0), 0);
  const safeTotal = numericTotal || 1;
  let current = 0;
  const gradient = segments.length
    ? segments.map((item) => {
      const start = current;
      current += (Number(item.value || 0) / safeTotal) * 100;
      return `${item.color} ${start.toFixed(2)}% ${current.toFixed(2)}%`;
    }).join(", ")
    : "#e2e8f0 0% 100%";
  return `
    <section class="panel chart-panel ${compact ? "compact-donut-panel" : ""}">
      <div class="panel-title"><div><h2>${escapeHtml(title)}</h2>${subtitle ? `<p class="hint">${escapeHtml(subtitle)}</p>` : ""}</div></div>
      <div class="donut-row">
        <div class="donut" style="background: conic-gradient(${gradient});"><span>${escapeHtml(centerLabel || String(numericTotal || 0))}</span></div>
        <div class="legend-list">
          ${segments.map((item) => `
            <button class="${activeValue === item.label ? "active" : ""}" data-action="visual-filter" data-scope="${scope}" data-filter="${filterKey}" data-value="${escapeHtml(item.label)}">
              <i style="background:${item.color}"></i>
              <span>${escapeHtml(item.label)}</span>
              <strong>${escapeHtml(String(item.valueLabel || item.value))}</strong>
            </button>
          `).join("")}
        </div>
      </div>
    </section>
  `;
}

function renderBarPanel({ title, subtitle, segments, scope, filterKey, activeValue, valueFormatter = (value) => value, compact = false }) {
  const max = Math.max(...segments.map((item) => Number(item.value || 0)), 1);
  return `
    <section class="panel chart-panel ${compact ? "compact-bar-panel" : ""}">
      <div class="panel-title"><div><h2>${escapeHtml(title)}</h2>${subtitle ? `<p class="hint">${escapeHtml(subtitle)}</p>` : ""}</div></div>
      <div class="bar-list">
        ${segments.map((item) => {
          const width = Math.max(5, Math.round((Number(item.value || 0) / max) * 100));
          const tone = item.tone || (item.label.includes("Проср") || item.label.includes("Не обеспеч") || item.label.includes("Крит") ? "danger" : item.label.includes("Част") || item.label.includes("Сегодня") || item.label.includes("Истека") ? "warning" : "");
          return `
            <button class="bar-row ${tone} ${activeValue === item.label ? "active" : ""}" data-action="visual-filter" data-scope="${scope}" data-filter="${filterKey}" data-value="${escapeHtml(item.label)}">
              <span>${escapeHtml(item.label)}</span>
              <div><i style="width:${width}%; background:${item.color || ""};"></i></div>
              <strong>${escapeHtml(String(valueFormatter(item.value)))}</strong>
            </button>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function getTaskUrgencyTone(urgency) {
  if (urgency === "Просрочены") return "danger";
  if (urgency === "Сегодня") return "warning";
  if (urgency === "На неделе") return "info";
  return "ok";
}

function getTaskPriorityTone(priority) {
  if (priority === "Критический") return "danger";
  if (priority === "Высокий") return "warning";
  if (priority === "Средний") return "info";
  return "ok";
}

function getTaskQueueWeight(task) {
  const urgencyRank = { "Просрочены": 0, "Сегодня": 1, "На неделе": 2, "В срок": 3 };
  const priorityRank = { "Критический": 0, "Высокий": 1, "Средний": 2, "Низкий": 3 };
  return (urgencyRank[getTaskUrgency(task)] ?? 4) * 10 + (priorityRank[task.priority] ?? 4);
}

function isManagerDecisionTask(task) {
  if (!task || isTaskClosed(task)) return false;
  const urgency = getTaskUrgency(task);
  const isUrgent = urgency === "Просрочены" || urgency === "Сегодня";
  const needsEscalation = ["Критический", "Высокий"].includes(task.priority) || ["Ожидание", "Отложена"].includes(task.status);
  return isUrgent && needsEscalation;
}

function getManagerDecisionTasks(rows, limit = 4) {
  return [...rows]
    .filter(isManagerDecisionTask)
    .sort((a, b) => getTaskQueueWeight(a) - getTaskQueueWeight(b) || String(a.dueDate).localeCompare(String(b.dueDate)))
    .slice(0, limit);
}

function renderTaskMetricStrip(cards) {
  return `
    <div class="task-metric-strip">
      ${cards.map((card) => `
        <button type="button" class="task-metric ${card.tone || ""} ${card.active ? "active" : ""}" ${card.action || ""}>
          <span>${escapeHtml(card.label)}</span>
          <strong>${escapeHtml(card.value)}</strong>
          <small>${escapeHtml(card.hint || "")}</small>
        </button>
      `).join("")}
    </div>
  `;
}

function renderTaskSlaBoard(segments, total, visual) {
  return `
    <section class="panel task-sla-board">
      <div class="panel-title">
        <div><h2>SLA и сроки</h2><p class="hint">Приоритет по срокам</p></div>
      </div>
      <div class="task-sla-tiles">
        ${segments.map((item) => {
          const value = Number(item.value || 0);
          const percent = total ? Math.round((value / total) * 100) : 0;
          const tone = getTaskUrgencyTone(item.label);
          return `
            <button type="button" class="task-sla-tile ${tone} ${visual.urgency === item.label ? "active" : ""}" data-action="visual-filter" data-scope="tasks" data-filter="urgency" data-value="${escapeHtml(item.label)}">
              <span><i></i>${escapeHtml(item.label)}</span>
              <strong>${value}</strong>
              <small>${percent}% очереди</small>
            </button>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function renderTaskTypeBoard(segments, total, visual) {
  const visible = segments.slice(0, 6);
  const restValue = segments.slice(6).reduce((sum, item) => sum + Number(item.value || 0), 0);
  const displaySegments = restValue
    ? [...visible, { label: "Другие типы", value: restValue, color: "#94a3b8", summary: true }]
    : visible;
  return `
    <section class="panel task-type-board">
      <div class="panel-title">
        <div><h2>Типы задач</h2><p class="hint">Доли в очереди</p></div>
      </div>
      <div class="task-type-distribution" aria-hidden="true">
        ${displaySegments.map((item) => {
          const percent = total ? Math.round((Number(item.value || 0) / total) * 100) : 0;
          return `<span style="--slice-width:${percent}%; --task-color:${item.color}"></span>`;
        }).join("")}
      </div>
      <div class="task-type-list">
        ${displaySegments.map((item) => {
          const percent = total ? Math.round((Number(item.value || 0) / total) * 100) : 0;
          const content = `
            <span><i></i>${escapeHtml(item.label)}</span>
            <strong>${escapeHtml(String(item.value))}</strong>
            <small>${percent}%</small>
          `;
          return item.summary
            ? `<div class="task-type-rank muted" style="--task-color:${item.color}">${content}</div>`
            : `<button type="button" class="task-type-rank ${visual.type === item.label ? "active" : ""}" style="--task-color:${item.color}" data-action="visual-filter" data-scope="tasks" data-filter="type" data-value="${escapeHtml(item.label)}">${content}</button>`;
        }).join("")}
      </div>
    </section>
  `;
}

function renderTaskAssigneeBoard(segments, activeAssignee) {
  const max = Math.max(...segments.map((item) => Number(item.value || 0)), 1);
  return `
    <section class="panel task-assignee-board">
      <div class="panel-title">
        <div><h2>Загрузка исполнителей</h2><p class="hint">Активные задачи по ответственным</p></div>
      </div>
      <div class="task-assignee-list">
        ${segments.map((item) => {
          const width = Math.max(8, Math.round((Number(item.value || 0) / max) * 100));
          return `
            <button type="button" class="task-assignee-row ${activeAssignee === item.label ? "active" : ""}" data-action="task-assignee-filter" data-value="${escapeHtml(item.label)}">
              <span>${escapeHtml(item.label)}</span>
              <i><b style="width:${width}%"></b></i>
              <strong>${escapeHtml(String(item.value))}</strong>
            </button>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function renderTaskQueuePanel(queueRows, visibleCount, baseCount) {
  return `
    <section class="panel task-queue-panel">
      <div class="panel-title">
        <div><h2>Очередь обработки</h2><p class="hint">Сначала показываются срочные и критические задачи</p></div>
        <span class="panel-note">${visibleCount} из ${baseCount}</span>
      </div>
      ${queueRows.length ? `
        <div class="task-queue-list">
          ${queueRows.map((task) => {
            const collaterals = getTaskCollaterals(task);
            const collateral = collaterals[0] || getCollateral(task.collateralId);
            const collateralText = collaterals.length > 1
              ? `${collaterals.length} залогов`
              : collateral?.description || task.collateralId || "Без объекта";
            const urgency = getTaskUrgency(task);
            return `
              <article class="task-queue-item ${getTaskUrgencyTone(urgency)}">
                <div>
                  <a class="link registry-object-link" href="#/app/tasks/${escapeHtml(task.id)}">${escapeHtml(task.id)}</a>
                  <strong>${escapeHtml(task.type)}</strong>
                  <small>${escapeHtml(getTaskClientSummary(task, collaterals))} · ${escapeHtml(collateralText)}</small>
                </div>
                <div>
                  ${badge(task.priority)}
                  <small>${escapeHtml(task.dueDate)} · ${escapeHtml(urgency)}</small>
                </div>
              </article>
            `;
          }).join("")}
        </div>
      ` : renderEmpty("Очередь пуста", "Измените фильтры или выберите другой срез.", "tasks")}
    </section>
  `;
}

function renderTaskRegistryToolbar(filteredRows, activeTab, role, activeFilterCount, rowsCount, baseCount) {
  return `
    <section class="task-registry-toolbar">
      <div>
        ${renderTaskRegistryTabs(filteredRows, activeTab, role)}
      </div>
    </section>
  `;
}

function renderTaskRiskHeatmapPanel(baseRows, visual) {
  const urgencyOrder = ["Просрочены", "Сегодня", "На неделе", "В срок"];
  const activeRows = baseRows.filter((task) => !isTaskClosed(task));
  const typeRows = toSegments(countBy(activeRows, (task) => task.type))
    .map((typeItem) => {
      const counts = Object.fromEntries(urgencyOrder.map((urgency) => [
        urgency,
        activeRows.filter((task) => task.type === typeItem.label && getTaskUrgency(task) === urgency).length
      ]));
      const focus = counts["Просрочены"] + counts["Сегодня"];
      const score = counts["Просрочены"] * 3 + counts["Сегодня"] * 2 + counts["На неделе"];
      return { ...typeItem, counts, focus, score };
    })
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score || Number(b.value || 0) - Number(a.value || 0));
  const weekRiskCount = activeRows.filter((task) => ["Просрочены", "Сегодня", "На неделе"].includes(getTaskUrgency(task))).length;
  const attentionTasks = getManagerDecisionTasks(activeRows, 3);
  return `
    <section class="panel task-risk-heatmap-panel">
      <div class="panel-title">
        <div><h2>Проблемные зоны</h2><p class="hint">Сроковой риск по типам задач</p></div>
        <span class="panel-note">До недели: ${weekRiskCount}</span>
      </div>
      ${typeRows.length ? `
        <div class="task-risk-matrix">
          <div class="task-risk-matrix-head">
            <span>Тип задачи</span>
            <span>Что требует внимания</span>
            <span>Проср.</span>
            <span>Сегодня</span>
            <span>Неделя</span>
            <span>Всего</span>
          </div>
          ${typeRows.map((typeItem) => {
            const taskType = typeItem.label;
            const total = Number(typeItem.value || 0);
            const overdue = Number(typeItem.counts["Просрочены"] || 0);
            const today = Number(typeItem.counts["Сегодня"] || 0);
            const week = Number(typeItem.counts["На неделе"] || 0);
            const overdueAssignees = toSegments(countBy(
              activeRows.filter((task) => task.type === taskType && getTaskUrgency(task) === "Просрочены"),
              (task) => task.assignee
            ));
            const visibleOverdueAssignees = overdueAssignees.slice(0, 2);
            const hiddenOverdueAssignees = overdueAssignees.length - visibleOverdueAssignees.length;
            const overdueAssigneeDetails = visibleOverdueAssignees.length
              ? `${visibleOverdueAssignees.map((item) => `${item.label} - ${item.value}`).join(" · ")}${hiddenOverdueAssignees > 0 ? ` · + еще ${hiddenOverdueAssignees}` : ""}`
              : "";
            const reasonTone = overdue ? "danger" : today ? "warning" : "info";
            const reasonTitle = overdue ? `Просрочка: ${overdue}` : today ? `Истекает сегодня: ${today}` : `На неделе: ${week}`;
            const reasonDetails = overdue
              ? overdueAssigneeDetails
              : today
                ? `На неделе ${week} · просрочек нет`
                : `Просрочек нет · сегодня 0`;
            return `
              <button type="button" class="task-risk-matrix-row ${visual.type === taskType ? "active" : ""}" data-action="task-risk-row" data-type="${escapeHtml(taskType)}">
                <span title="${escapeHtml(taskType)}"><i style="background:${typeItem.color}"></i>${escapeHtml(taskType)}</span>
                <span class="task-risk-reason ${reasonTone}">
                  <b>${escapeHtml(reasonTitle)}</b>
                  <small>${escapeHtml(reasonDetails)}</small>
                </span>
                <strong class="danger">${overdue}</strong>
                <strong class="warning">${today}</strong>
                <strong class="info">${week}</strong>
                <strong>${total}</strong>
              </button>
            `;
          }).join("")}
        </div>
        <div class="task-attention-list">
          <div class="task-attention-title">
            <h3>Требуют решения</h3>
            <span>${attentionTasks.length}</span>
          </div>
          ${attentionTasks.length ? attentionTasks.map((task) => `
            <article class="task-attention-item ${getTaskUrgencyTone(getTaskUrgency(task))}">
              <div>
                <a class="link registry-object-link" href="#/app/tasks/${escapeHtml(task.id)}">${escapeHtml(task.id)}</a>
                <strong>${escapeHtml(task.type)}</strong>
                <small>${escapeHtml(task.assignee)} · ${escapeHtml(task.dueDate)} · ${escapeHtml(getTaskUrgency(task))}</small>
              </div>
              ${badge(task.priority)}
            </article>
          `).join("") : `<div class="task-attention-empty">Нет срочных задач с высоким приоритетом или проблемным статусом</div>`}
        </div>
      ` : renderEmpty("Сроковых рисков нет", "Нет просроченных задач и задач со сроком в ближайшую неделю.", "tasks")}
    </section>
  `;
}

function getTaskRegistryTypeOptions(direction) {
  const defaultTypes = taskTypes.filter((type) => getTaskDirection({ type }) === direction);
  const dataTypes = state.data.tasks
    .filter((task) => getTaskDirection(task) === direction)
    .map((task) => task.type);
  return ["", ...uniqueItems([...defaultTypes, ...dataTypes])];
}

function getTaskRegistryStatusOptions(direction) {
  const dataStatuses = state.data.tasks
    .filter((task) => getTaskDirection(task) === direction)
    .map((task) => task.status);
  return ["", ...uniqueItems([...TASK_STATUSES, ...dataStatuses].filter(Boolean))];
}

function getTaskRegistryAssigneeOptions(direction) {
  const dataAssignees = state.data.tasks
    .filter((task) => getTaskDirection(task) === direction)
    .map((task) => task.assignee);
  return ["", ...uniqueItems([...employees, ...dataAssignees].filter(Boolean))];
}

function getTaskRegistryApplicationSearch(task, application) {
  return [application?.number, application?.id, task?.applicationNumber, task?.applicationId].filter(Boolean).join(" ");
}

function getTaskRegistryCollateralSearch(collaterals, task) {
  return [
    task?.collateralId,
    ...(task?.collateralIds || []),
    ...collaterals.map((item) => getCollateralRegistrySearchText(item))
  ].filter(Boolean).join(" ");
}

function getTaskRegistryContractSearch(task, contracts) {
  return [
    task?.contractNumber,
    task?.contractId,
    ...contracts.flatMap((contract) => [contract?.id, contract?.number])
  ].filter(Boolean).join(" ");
}

function getTaskRegistryClientSearch(task, application, contracts, collaterals) {
  return [
    getApplicationClientName(application),
    getApplicationInn(application),
    task?.dealClientName,
    task?.dealClientInn,
    task?.participantName,
    task?.participantInn,
    ...contracts.flatMap((contract) => [
      contract?.clientName,
      contract?.inn,
      ...(contract?.participants || []).flatMap((item) => [item.name, item.idn])
    ]),
    ...collaterals.flatMap((collateral) => [collateral?.clientName, collateral?.clientId])
  ].filter(Boolean).join(" ");
}

function getTaskRegistryPledgorSearch(collaterals) {
  return collaterals
    .flatMap((collateral) => {
      const pledgor = getMainPledgor(collateral);
      return [pledgor.name, pledgor.idn, collateral?.clientName, collateral?.clientId];
    })
    .filter(Boolean)
    .join(" ");
}

function getTaskRegistryClientDisplay(task, application, contracts, collaterals) {
  const applicationClient = getApplicationClientName(application);
  if (applicationClient && applicationClient !== "-") return applicationClient;
  return getTaskClientSummary(task, collaterals) || contracts[0]?.clientName || task?.dealClientName || "-";
}

function getTaskRegistryAuthor(task) {
  return getTaskInitiator(task);
}

function getTaskRegistryVerifier(task) {
  return task?.verifier || task?.approval?.verifier || task?.approval?.approver || "Мария Петрова";
}

function getTaskRegistryAppraiser(task) {
  if (task?.appraiser) return task.appraiser;
  if (isRevaluationTaskType(task?.type)) return task?.assignee || "Дмитрий Орлов";
  return "-";
}

function getTaskRegistryInspectionDone(task, collaterals) {
  if (task?.inspectionDone !== undefined) return task.inspectionDone ? "Да" : "Нет";
  const hasInspectionResult = collaterals.some((collateral) => {
    const last = getLatestCompletedInspection(collateral);
    return Boolean(last?.date || collateral?.monitoring?.lastInspection);
  });
  return hasInspectionResult ? "Да" : "Нет";
}

function getTaskRegistryRemainingTerm(task) {
  const days = daysUntil(task?.dueDate);
  if (days === null) return getTaskUrgency(task);
  if (days < 0) return `Просрочено ${Math.abs(days)} дн.`;
  if (days === 0) return "Сегодня";
  return `${days} дн.`;
}

function getTaskRegistryExpertComment(task) {
  return task?.negativeConclusionReason || task?.expertComment || task?.result || "-";
}

function getTaskRegistryPurpose(task, application) {
  return application ? getApplicationPurpose(application) : (getTaskApplicationPurposeValue(task) || "-");
}

function getTaskRegistryInitiatorSegment(task, application) {
  return application ? getApplicationInitiatorSegment(application) : (task?.initiatorSegment || "-");
}

function getTaskRegistryCity(collaterals) {
  const cities = uniqueItems(collaterals.map((collateral) =>
    collateral?.fields?.["Город"]
    || String(collateral?.address || "").split(",")[0]
    || collateral?.region
  ).filter(Boolean));
  return summarizeNames(cities, 2);
}

function getTaskRegistryCollateralType(collaterals) {
  return summarizeNames(collaterals.map(getCollateralTypeLabel), 2);
}

function getTaskRegistryInspectionPurpose(task, application) {
  return application ? getApplicationPurpose(application) : (getTaskApplicationPurposeValue(task) || "Проверка предмета залога");
}

function getTaskRegistryInspectionMethod(task) {
  return task?.inspectionVisitMethod || task?.inspectionMethod || (isDocumentaryInspectionTask(task) ? "Документарная проверка" : "Сотрудник банка (регионы)");
}

function getTaskRegistrationStatus(task, collaterals) {
  const statuses = uniqueItems([
    ...Object.values(task?.registrationStatuses || {}),
    ...collaterals.map((collateral) => collateral?.encumbrances?.[0]?.status)
  ].filter(Boolean));
  return summarizeNames(statuses, 2) || "Готовится регистрация";
}

function getTaskRegistrationBasis(task, application) {
  return task?.registrationBasis || (application ? getApplicationPurpose(application) : "") || "Регистрация предметов залога по заявке";
}

function getTaskRegistrationConclusions(task) {
  return task?.registrationConclusion || task?.expertConclusion || task?.result || "Проверки перед регистрацией в работе";
}

function getTaskRegistrationNumberDate(collaterals) {
  const values = uniqueItems(collaterals.flatMap((collateral) => (collateral?.encumbrances || []).map((encumbrance) =>
    [encumbrance.number, encumbrance.date].filter(Boolean).join(" от ")
  )).filter(Boolean));
  return values.length ? values.join(", ") : "-";
}

function getTaskRegistryColumns(direction) {
  const baseColumns = [
    { label: "Задача", render: (task) => `<a class="link registry-object-link" href="#/app/tasks/${escapeHtml(task.id)}">${escapeHtml(task.id)}</a>` },
    { label: "Заявка", render: (task) => renderTaskRegistryApplicationCell(task) },
    { label: "Клиент", render: (task, ctx) => escapeHtml(getTaskRegistryClientDisplay(task, ctx.application, ctx.contracts, ctx.collaterals)) },
    { label: "Тип задачи", render: (task) => escapeHtml(task.type) },
    { label: "Автор", render: (task) => escapeHtml(getTaskRegistryAuthor(task)) },
    { label: "Договор", render: (task, ctx) => renderTaskRegistryContractCell(task, ctx.contracts) },
    { label: "Залог", render: (task, ctx) => renderTaskRegistryCollateralCell(task, ctx.collaterals) },
    { label: "Залогодатель", render: (_task, ctx) => renderTaskRegistryPledgorCell(ctx.collaterals) }
  ];
  const commonTail = [
    { label: "Исполнитель", render: (task) => escapeHtml(task.assignee || "-") },
    { label: "Дата и время создания", render: (task) => escapeHtml(getTaskCreatedDateTime(task)) },
    { label: "Срок исполнения задачи", render: (task) => escapeHtml(task.dueDate || "-") },
    { label: "Статус", render: (task) => badge(task.status) }
  ];
  if (direction === "inspection") {
    return [
      ...baseColumns,
      { label: "Город", render: (_task, ctx) => escapeHtml(getTaskRegistryCity(ctx.collaterals)) },
      { label: "Вид залога", render: (_task, ctx) => escapeHtml(getTaskRegistryCollateralType(ctx.collaterals)) },
      ...commonTail,
      { label: "Цель осмотра", render: (task, ctx) => escapeHtml(getTaskRegistryInspectionPurpose(task, ctx.application)) },
      { label: "Способ проведения осмотра", render: (task) => escapeHtml(getTaskRegistryInspectionMethod(task)) },
      { label: "Остаток срока", render: (task) => badge(getTaskRegistryRemainingTerm(task), getTaskUrgencyTone(getTaskUrgency(task))) }
    ];
  }
  if (direction === "registration") {
    return [
      ...baseColumns,
      ...commonTail,
      { label: "Цель", render: (task, ctx) => escapeHtml(getTaskRegistryPurpose(task, ctx.application)) },
      { label: "Статус регистрации", render: (task, ctx) => badge(getTaskRegistrationStatus(task, ctx.collaterals)) },
      { label: "Основание", render: (task, ctx) => escapeHtml(getTaskRegistrationBasis(task, ctx.application)) },
      { label: "Выводы", render: (task) => escapeHtml(getTaskRegistrationConclusions(task)) },
      { label: "Остаток срока", render: (task) => badge(getTaskRegistryRemainingTerm(task), getTaskUrgencyTone(getTaskUrgency(task))) },
      { label: "Сегмент инициатора", render: (task, ctx) => escapeHtml(getTaskRegistryInitiatorSegment(task, ctx.application)) },
      { label: "Рег. номер / дата", render: (_task, ctx) => escapeHtml(getTaskRegistrationNumberDate(ctx.collaterals)) }
    ];
  }
  return [
    ...baseColumns,
    ...commonTail,
    { label: "Верификатор", render: (task) => escapeHtml(getTaskRegistryVerifier(task)) },
    { label: "Оценщик", render: (task) => escapeHtml(getTaskRegistryAppraiser(task)) },
    { label: "Осмотр проведен", render: (task, ctx) => badge(getTaskRegistryInspectionDone(task, ctx.collaterals), getTaskRegistryInspectionDone(task, ctx.collaterals) === "Да" ? "ok" : "warn") },
    { label: "Остаток срока", render: (task) => badge(getTaskRegistryRemainingTerm(task), getTaskUrgencyTone(getTaskUrgency(task))) },
    { label: "Комментарий к заключению", render: (task) => escapeHtml(getTaskRegistryExpertComment(task)) },
    { label: "Цель", render: (task, ctx) => escapeHtml(getTaskRegistryPurpose(task, ctx.application)) },
    { label: "Сегмент инициатора", render: (task, ctx) => escapeHtml(getTaskRegistryInitiatorSegment(task, ctx.application)) }
  ];
}

function renderTaskRegistryTable(rows, direction) {
  const columns = getTaskRegistryColumns(direction);
  return `
    <table class="task-table-modern task-table-modern--${escapeHtml(direction)}">
      <thead><tr>${columns.map((column) => `<th>${escapeHtml(column.label)}</th>`).join("")}</tr></thead>
      <tbody>${rows.length ? rows.map((task) => {
        const collaterals = getTaskCollaterals(task);
        const contracts = getTaskContracts(task, collaterals);
        const application = getTaskApplication(task);
        const ctx = { collaterals, contracts, application };
        return `<tr>${columns.map((column) => `<td>${column.render(task, ctx)}</td>`).join("")}</tr>`;
      }).join("") : `<tr><td colspan="${columns.length}"><span class="muted">Задачи не найдены</span></td></tr>`}</tbody>
    </table>
  `;
}

function renderTasksRegistry(query = new URLSearchParams(), direction = getAvailableTaskDirections(getRole())[0] || "evaluation") {
  if (query?.has("applicationNumber")) {
    state.filters.tasks.applicationNumber = query.get("applicationNumber") || "";
  }
  const role = getRole();
  if (!canViewTaskDirection(direction, role)) return renderNotFound("Раздел недоступен", getDefaultRouteForRole(role));
  const config = getTaskDirectionConfig(direction);
  const filters = state.filters.tasks;
  const visual = state.visualFilters.tasks;
  const activeTab = state.taskRegistryTab || "mine";
  const filteredRows = state.data.tasks.filter((task) => {
    if (getTaskDirection(task) !== direction) return false;
    const collaterals = getTaskCollaterals(task);
    const contracts = getTaskContracts(task, collaterals);
    const application = getTaskApplication(task);
    return matches(task.id, filters.number)
      && matches(getTaskRegistryApplicationSearch(task, application), filters.applicationNumber)
      && matches(getTaskRegistryClientSearch(task, application, contracts, collaterals), filters.clientName)
      && matches(getTaskRegistryContractSearch(task, contracts), filters.contractNumber)
      && matches(getTaskRegistryCollateralSearch(collaterals, task), filters.collateralId)
      && matches(task.type, filters.type)
      && matches(task.status, filters.status)
      && matches(task.assignee, filters.assignee)
      && matches(getTaskRegistryInitiatorSegment(task, application), filters.initiatorSegment)
      && matches(getTaskRegistryPledgorSearch(collaterals), filters.pledgor)
      && matchesDateOnlyRange(getTaskCreatedDateTime(task), filters.createdFrom, filters.createdTo)
      && matchesDateOnlyRange(task.dueDate, filters.dueFrom, filters.dueTo);
  });
  const baseRows = filteredRows.filter((task) => matchesTaskRegistryTab(task, activeTab, role));
  const rows = baseRows.filter((task) =>
    (!visual.type || task.type === visual.type)
    && (!visual.urgency || getTaskUrgency(task) === visual.urgency)
    && (!visual.status || task.status === visual.status)
    && (!visual.priority || task.priority === visual.priority)
  );
  const taskTypeOptions = getTaskRegistryTypeOptions(direction);
  const activeFilterCount = Object.values(filters).filter(Boolean).length + Object.values(visual).filter(Boolean).length;
  return `
    <section class="registry-work-area registry-work-area-tasks">
      ${renderPageHeader(config.title, config.description)}
      <div class="task-registry-workspace">
        ${renderTaskRegistryToolbar(filteredRows, activeTab, role, activeFilterCount, rows.length, baseRows.length)}
        <section class="panel task-filter-panel">
          <div class="filter-grid registry-filter-grid tasks-filter-grid">
            ${filterInput("tasks", "number", "Номер задачи")}
            ${filterInput("tasks", "applicationNumber", "Номер заявки")}
            ${filterInput("tasks", "clientName", "Клиент")}
            ${filterInput("tasks", "contractNumber", "Номер договора")}
            ${filterInput("tasks", "collateralId", "Залог")}
            ${filterSelect("tasks", "type", "Тип задачи", taskTypeOptions)}
            ${filterSelect("tasks", "status", "Статус", getTaskRegistryStatusOptions(direction))}
            ${filterSelect("tasks", "assignee", "Исполнитель", getTaskRegistryAssigneeOptions(direction))}
            ${filterSelect("tasks", "initiatorSegment", "Сегмент инициатора", getApplicationInitiatorSegmentOptions())}
            ${filterInput("tasks", "pledgor", "Залогодатель")}
            ${filterDateRange("tasks", "createdFrom", "createdTo", "Дата и время создания")}
            ${filterDateRange("tasks", "dueFrom", "dueTo", "Срок исполнения задачи")}
            <button class="btn btn-secondary" data-action="reset-filters" data-scope="tasks">Сбросить</button>
          </div>
        </section>
        <section class="panel table-panel task-table-panel" data-registry-table="tasks" tabindex="-1">
          <div class="panel-title"><h2>${escapeHtml(config.label)}</h2><span class="panel-note">${rows.length} из ${baseRows.length}</span></div>
          ${renderTaskRegistryTable(rows, direction)}
        </section>
      </div>
    </section>
  `;
}

function renderContractsRegistry(query = new URLSearchParams()) {
  const filters = state.filters.contracts;
  const applicationNumber = query?.get("applicationNumber") || "";
  const application = getApplicationByNumber(applicationNumber);
  const applicationContractIds = new Set(application ? getApplicationContracts(application).map((contract) => contract.id) : []);
  const baseRows = state.data.contracts.filter((contract) =>
    matches(contract.number, filters.number)
    && matches(contract.clientName, filters.clientName)
    && matches(contract.product, filters.product)
    && matches(contract.status, filters.status)
    && matches(contract.coverageStatus, filters.coverageStatus)
    && matches(getContractCollateralSearchText(contract), filters.collateralId)
    && (!applicationNumber || applicationContractIds.has(contract.id))
  );
  const rows = baseRows;
  const contractStatusOptions = getContractStatusOptions();
  const productOptions = getContractProductOptions();
  const coverageStatusOptions = getContractCoverageStatusOptions();
  return `
    <section class="registry-work-area registry-work-area-contracts">
      ${renderPageHeader("Реестр договоров", "Договоры, остатки долга, покрытие и связанные залоги.")}
      <section class="panel">
        <div class="filter-grid registry-filter-grid contracts-filter-grid">
          ${filterInput("contracts", "number", "Номер договора")}
          ${filterInput("contracts", "clientName", "Клиент по договору")}
          ${filterSelect("contracts", "product", "Продукт", productOptions)}
          ${filterSelect("contracts", "status", "Статус договора", contractStatusOptions)}
          ${filterSelect("contracts", "coverageStatus", "Статус покрытия", coverageStatusOptions)}
          ${filterInput("contracts", "collateralId", "Залог")}
          <button class="btn btn-secondary" data-action="reset-filters" data-scope="contracts">Сбросить</button>
        </div>
      </section>
      <section class="panel table-panel" data-registry-table="contracts" tabindex="-1">
        <div class="panel-title"><h2>Договоры</h2><span class="panel-note">${rows.length} записей${applicationNumber ? `, заявка ${escapeHtml(applicationNumber)}` : ""}</span></div>
        <table class="contracts-table">
          <thead><tr><th>Договор</th><th>Клиент по договору</th><th>Продукт</th><th>Остаток долга</th><th>Аллоцированная стоимость</th><th>Залог</th><th>Статус договора</th><th>Статус покрытия</th></tr></thead>
          <tbody>${rows.map((contract) => `
            <tr>
              <td>${escapeHtml(contract.number)}</td>
              <td>${escapeHtml(contract.clientName)}</td>
              <td>${escapeHtml(contract.product)}</td>
              <td>${renderContractDebtCell(contract)}</td>
              <td>${formatMoney(contract.allocatedValue || 0)}</td>
              <td>${renderContractRegistryCollateralCell(contract)}</td>
              <td>${badge(contract.status)}</td>
              <td>${badge(contract.coverageStatus, contract.coverageStatus === "Не обеспечено" || contract.coverageStatus === "Недостаточное" ? "danger" : contract.coverageStatus === "Частичное" ? "warn" : "ok")}</td>
            </tr>
          `).join("")}</tbody>
        </table>
      </section>
    </section>
  `;
}

function renderContractRegistryCollateralCell(contract) {
  const rows = (contract?.collateralIds || []).map(getCollateral).filter(Boolean);
  if (!rows.length) return `<span class="muted">-</span>`;
  if (rows.length === 1) {
    const collateral = rows[0];
    return `<a class="link registry-object-link" href="#/app/collaterals/${escapeHtml(collateral.id)}">${escapeHtml(collateral.id)}</a>`;
  }
  return `<span>${rows.length} ${pluralize(rows.length, "залог", "залога", "залогов")}</span>`;
}

function getContractsDeficit(contracts) {
  return sumBy(contracts, (contract) => Math.max(0, getContractDebtRub(contract) - Number(contract.allocatedValue || 0)));
}

function getContractCoverageBucket(contract) {
  const debt = getContractDebtRub(contract);
  const allocated = Number(contract.allocatedValue || 0);
  if (!allocated) return { label: "Нет активного залога", color: chartPalette[4], tone: "danger" };
  if (debt > allocated) return { label: "Дефицит обеспечения", color: chartPalette[3], tone: "danger" };
  if (contract.coverageStatus === "Частичное" || allocated / Math.max(1, debt) < 1.15) return { label: "Частичное покрытие", color: chartPalette[2], tone: "warn" };
  return { label: "Полное покрытие", color: chartPalette[0], tone: "ok" };
}

function getContractLtvBucket(contract) {
  const ltv = Number(contract.ltv || 0);
  if (ltv > 100) return { label: ">100% дефицит", color: chartPalette[4], tone: "danger", min: 101 };
  if (ltv > 90) return { label: "90-100% высокий риск", color: chartPalette[3], tone: "warn", min: 91 };
  if (ltv > 70) return { label: "70-90% наблюдение", color: chartPalette[2], tone: "warn", min: 71 };
  return { label: "до 70% норма", color: chartPalette[0], tone: "ok", min: 0 };
}


function getContractCoverageSegments(contracts) {
  const order = ["Полное покрытие", "Частичное покрытие", "Дефицит обеспечения", "Нет активного залога"];
  const buckets = contracts.map(getContractCoverageBucket);
  return order.map((label) => {
    const bucket = buckets.find((item) => item.label === label);
    return { label, value: buckets.filter((item) => item.label === label).length, color: bucket?.color || chartPalette[0] };
  }).filter((item) => item.value > 0);
}

function getContractLtvSegments(contracts) {
  const order = ["до 70% норма", "70-90% наблюдение", "90-100% высокий риск", ">100% дефицит"];
  const buckets = contracts.map(getContractLtvBucket);
  return order.map((label) => {
    const bucket = buckets.find((item) => item.label === label);
    return { label, value: buckets.filter((item) => item.label === label).length, color: bucket?.color || chartPalette[0], tone: bucket?.tone || "neutral" };
  }).filter((item) => item.value > 0);
}

function getContractMaturityBucket(contract) {
  const days = daysUntil(contract?.endDate);
  if (days === null) return { label: "Срок не задан", color: chartPalette[5], tone: "neutral" };
  if (days < 0) return { label: "Срок истек", color: chartPalette[4], tone: "danger" };
  if (days <= 180) return { label: "до 6 месяцев", color: chartPalette[3], tone: "warn" };
  if (days <= 365) return { label: "6-12 месяцев", color: chartPalette[2], tone: "warn" };
  if (days <= 1095) return { label: "1-3 года", color: chartPalette[0], tone: "info" };
  return { label: "более 3 лет", color: chartPalette[1], tone: "ok" };
}

function isContractMaturingWithin12Months(contract) {
  const days = daysUntil(contract?.endDate);
  return days !== null && days >= 0 && days <= 365;
}

function getContractMaturitySegments(contracts) {
  const order = ["Срок истек", "до 6 месяцев", "6-12 месяцев", "1-3 года", "более 3 лет", "Срок не задан"];
  const buckets = contracts.map(getContractMaturityBucket);
  return order.map((label) => {
    const bucket = buckets.find((item) => item.label === label);
    return { label, value: buckets.filter((item) => item.label === label).length, color: bucket?.color || chartPalette[0], tone: bucket?.tone || "neutral" };
  }).filter((item) => item.value > 0);
}

function getContractGszExposureSegments(contracts) {
  const totals = new Map();
  contracts.forEach((contract) => {
    const label = contract.gsz || "ГСЗ не указана";
    totals.set(label, (totals.get(label) || 0) + getContractDebtRub(contract));
  });
  return [...totals.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([label, value], index) => ({ label, value, color: chartPalette[index % chartPalette.length] }));
}

function renderContractLtvRiskPanel(segments, activeValue) {
  const max = Math.max(...segments.map((item) => item.value), 1);
  return `
    <section class="panel chart-panel contract-ltv-panel">
      <div class="panel-title"><div><h2>LTV по зонам риска</h2><p class="hint">Чем выше LTV, тем меньше запас покрытия по договору.</p></div></div>
      <div class="ltv-risk-list">
        ${segments.map((item) => `
          <button class="ltv-risk-row ${item.tone || ""} ${activeValue === item.label ? "active" : ""}" data-action="visual-filter" data-scope="contracts" data-filter="ltv" data-value="${escapeHtml(item.label)}">
            <span>${escapeHtml(item.label)}</span>
            <div><i style="width:${Math.max(6, Math.round((item.value / max) * 100))}%; background:${item.color};"></i></div>
            <strong>${item.value}</strong>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function getContractStatusOptions() {
  const defaultStatuses = [
    "Активен",
    "На оформлении",
    "Приостановлен",
    "Просрочен",
    "Реструктурирован",
    "Завершен",
    "Закрыт",
    "Досрочно погашен",
    "Расторгнут",
    "Аннулирован"
  ];
  const dataStatuses = state.data.contracts.map((contract) => contract.status).filter(Boolean);
  return ["", ...[...new Set([...defaultStatuses, ...dataStatuses])]];
}

function getContractProductOptions() {
  return ["", ...uniqueItems(state.data.contracts.map((contract) => contract.product).filter(Boolean))];
}

function getContractCoverageStatusOptions() {
  const defaultStatuses = ["Полное", "Частичное", "Недостаточное", "Не обеспечено"];
  const dataStatuses = state.data.contracts.map((contract) => contract.coverageStatus).filter(Boolean);
  return ["", ...[...new Set([...defaultStatuses, ...dataStatuses])]];
}

function getContractCollateralSearchText(contract) {
  return (contract?.collateralIds || [])
    .map(getCollateral)
    .filter(Boolean)
    .map(getCollateralRegistrySearchText)
    .join(" ");
}

function getCollateralRegistrySearchText(collateral) {
  const fieldValues = Object.values(collateral?.fields || {}).join(" ");
  return [
    collateral?.id,
    getCollateralTypeLabel(collateral),
    getCollateralObjectIdentifier(collateral),
    collateral?.description,
    collateral?.name,
    collateral?.identifier,
    collateral?.identificationCode,
    fieldValues
  ].filter(Boolean).join(" ");
}

function getCollateralRegistryName(collateral) {
  return collateral?.name || collateral?.description || collateral?.id || "-";
}

function getCollateralRegistryClientSearchText(collateral) {
  const contracts = (collateral?.contractIds || []).map(getContract).filter(Boolean);
  return [
    collateral?.clientName,
    collateral?.clientId,
    ...contracts.flatMap((contract) => [contract?.clientName, contract?.inn])
  ].filter(Boolean).join(" ");
}

function getCollateralRegistryPledgorSearchText(collateral) {
  const pledgor = getMainPledgor(collateral);
  return [
    pledgor.name,
    pledgor.idn,
    ...(collateral?.pledgors || []).flatMap((item) => [item.name, item.idn])
  ].filter(Boolean).join(" ");
}

function getCollateralRegistryCreditContractText(collateral) {
  return (collateral?.contractIds || [])
    .map((id) => getContract(id)?.number || id)
    .filter(Boolean)
    .join(" ");
}

function getCollateralRegistryPledgeContractText(collateral) {
  return (collateral?.encumbrances || [])
    .map((encumbrance) => [encumbrance.number, encumbrance.contract].filter(Boolean).join(" "))
    .filter(Boolean)
    .join(" ");
}

function getCollateralRegistryLatestAppraisalDate(collateral) {
  const latest = getLatestCollateralEvaluation(collateral);
  return latest?.date || collateral?.evalDate || collateral?.appraisalDate || "-";
}

function renderCollateralsRegistry(query = new URLSearchParams()) {
  const role = getRole();
  const filters = state.filters.collaterals;
  const applicationNumber = query?.get("applicationNumber") || "";
  const application = getApplicationByNumber(applicationNumber);
  const applicationCollateralIds = new Set(application ? getApplicationCollaterals(application).map((collateral) => collateral.id) : []);
  const baseRows = state.data.collaterals.filter((item) => {
    const latestEvaluation = getLatestCollateralEvaluation(item);
    const fairValue = getEvaluationFairValue(latestEvaluation, item);
    return matches(getCollateralRegistryName(item), filters.name)
      && matches(getCollateralRegistrySearchText(item), filters.collateralId)
      && matches(getCollateralTypeLabel(item), filters.type)
      && matches(getCollateralRegistryClientSearchText(item), filters.clientName)
      && matches(getCollateralRegistryPledgorSearchText(item), filters.pledgor)
      && matches(getCollateralRegistryCreditContractText(item), filters.creditContractNumber)
      && matches(getCollateralRegistryPledgeContractText(item), filters.pledgeContractNumber)
      && matches(item.address || item.region, filters.address)
      && matchesNumericRange(item.marketValue, filters.marketFrom, filters.marketTo)
      && matchesNumericRange(item.pledgeValue, filters.pledgeFrom, filters.pledgeTo)
      && matchesNumericRange(fairValue, filters.fairFrom, filters.fairTo)
      && matchesDateOnlyRange(getCollateralRegistryLatestAppraisalDate(item), filters.appraisalDateFrom, filters.appraisalDateTo)
      && matches(getCollateralQualityClass(item), filters.quality)
      && matches(getCollateralStatusForFt(item), filters.status)
      && matches(item.description, filters.description)
      && (!applicationNumber || applicationCollateralIds.has(item.id));
  });
  const rows = baseRows;
  const types = FT_COLLATERAL_TYPE_OPTIONS;
  const statusOptions = ["", ...COLLATERAL_STATUS_OPTIONS];
  const qualityOptions = ["", ...uniqueItems(state.data.collaterals.map(getCollateralQualityClass).filter(Boolean))];
  const actions = hasPermission(role, "collateralEdit")
    ? `<button class="btn btn-secondary" data-action="open-new-collateral-form" data-context="registry">Добавить новый объект</button><button class="btn btn-secondary" data-action="open-import-collaterals">Загрузить объекты из таблицы</button>`
    : "";
  return `
    <section class="registry-work-area registry-work-area-collaterals">
      ${renderPageHeader("Реестр залогов", "Объекты залога, профильные идентификаторы, договоры, стоимости и статус объекта.", actions)}
      <section class="panel">
        <div class="filter-grid registry-filter-grid collaterals-filter-grid">
          ${filterInput("collaterals", "name", "Наименование залога")}
          ${filterInput("collaterals", "collateralId", "Залог")}
          ${filterSelect("collaterals", "type", "Вид залога", ["", ...types])}
          ${filterInput("collaterals", "clientName", "Клиент")}
          ${filterInput("collaterals", "pledgor", "Залогодатель")}
          ${filterInput("collaterals", "creditContractNumber", "Номер кредитного договора")}
          ${filterInput("collaterals", "pledgeContractNumber", "Номер договора залога")}
          ${filterInput("collaterals", "address", "Адрес")}
          ${filterInput("collaterals", "marketFrom", "Рыночная стоимость от")}
          ${filterInput("collaterals", "marketTo", "Рыночная стоимость до")}
          ${filterInput("collaterals", "pledgeFrom", "Залоговая стоимость от")}
          ${filterInput("collaterals", "pledgeTo", "Залоговая стоимость до")}
          ${filterInput("collaterals", "fairFrom", "Справедливая стоимость от")}
          ${filterInput("collaterals", "fairTo", "Справедливая стоимость до")}
          ${filterDateRange("collaterals", "appraisalDateFrom", "appraisalDateTo", "Дата последней оценки")}
          ${filterSelect("collaterals", "quality", "Категория качества", qualityOptions)}
          ${filterSelect("collaterals", "status", "Статус объекта", statusOptions)}
          ${filterInput("collaterals", "description", "Описание")}
          <button class="btn btn-secondary" data-action="reset-filters" data-scope="collaterals">Сбросить</button>
        </div>
      </section>
      <section class="panel table-panel" data-registry-table="collaterals" tabindex="-1">
        <div class="panel-title"><h2>Залоги</h2><span class="panel-note">${rows.length} объектов${applicationNumber ? `, заявка ${escapeHtml(applicationNumber)}` : ""}</span></div>
        <table class="collaterals-table">
          <thead><tr><th>ID</th><th>Наименование залога</th><th>Вид залога</th><th>Профильный идентификатор</th><th>Описание</th><th>Залогодатель</th><th>Клиент</th><th>Кредитный договор</th><th>Договор залога</th><th>Адрес</th><th>Рыночная</th><th>Залоговая</th><th>Справедливая</th><th>Дата последней оценки</th><th>Категория качества</th><th>Статус объекта</th></tr></thead>
          <tbody>${rows.length ? rows.map((item) => {
            const latestEvaluation = getLatestCollateralEvaluation(item);
            const fairValue = getEvaluationFairValue(latestEvaluation, item);
            const pledgor = getMainPledgor(item);
            return `
              <tr>
                <td><a class="link registry-object-link" href="#${escapeHtml(getCollateralCardRoute(item.id, application ? { application } : {}))}">${escapeHtml(item.id)}</a></td>
                <td>${escapeHtml(getCollateralRegistryName(item))}</td>
                <td>${escapeHtml(getCollateralTypeLabel(item))}</td>
                <td>${escapeHtml(getCollateralObjectIdentifier(item))}</td>
                <td>${escapeHtml(item.description || "-")}</td>
                <td>${escapeHtml(pledgor.name)}<br><small>${escapeHtml(pledgor.idn)}</small></td>
                <td>${escapeHtml(item.clientName || "-")}<br><small>${escapeHtml(item.clientId || "")}</small></td>
                <td>${renderCollateralRegistryContractsCell(item)}</td>
                <td>${renderCollateralRegistryPledgeContractsCell(item)}</td>
                <td>${escapeHtml(item.address || item.region || "-")}</td>
                <td>${formatMoney(item.marketValue)}</td>
                <td>${formatMoney(item.pledgeValue)}</td>
                <td>${formatMoney(fairValue)}</td>
                <td>${escapeHtml(getCollateralRegistryLatestAppraisalDate(item))}</td>
                <td>${escapeHtml(getCollateralQualityClass(item))}</td>
                <td>${badge(getCollateralStatusForFt(item))}</td>
              </tr>
            `;
          }).join("") : `<tr><td colspan="16"><span class="muted">Залоги не найдены</span></td></tr>`}</tbody>
        </table>
      </section>
    </section>
  `;
}

function renderCollateralRegistryContractsCell(collateral) {
  const contracts = (collateral?.contractIds || []).map(getContract).filter(Boolean);
  const numbers = uniqueItems(contracts.map((contract) => contract.number).filter(Boolean));
  if (!numbers.length) return `<span class="muted">-</span>`;
  return `<span class="contract-number-list">${numbers.map(escapeHtml).join(",<br>")}</span>`;
}

function renderCollateralRegistryPledgeContractsCell(collateral) {
  const rows = uniqueItems((collateral?.encumbrances || [])
    .map((encumbrance) => [encumbrance.number, encumbrance.date].filter(Boolean).join(" от "))
    .filter(Boolean));
  if (!rows.length) return `<span class="muted">-</span>`;
  return `<span class="contract-number-list">${rows.map(escapeHtml).join(",<br>")}</span>`;
}

function getApplicationStatusOptions() {
  return ["", ...uniqueItems([...APPLICATION_STATUSES, ...(state.data.applications || []).map((item) => item.status)].filter(Boolean))];
}

function getApplicationTypeFilterOptions() {
  return ["", ...uniqueItems([...APPLICATION_TYPES.map((item) => item.value), ...(state.data.applications || []).map(getApplicationType)].filter(Boolean))];
}

function getApplicationSubtypeFilterOptions() {
  return ["", ...uniqueItems([...(state.data.applications || []).map(getApplicationSubtype), ...APPLICATION_TYPES.flatMap((item) => item.subtypes)].filter(Boolean))];
}

function getApplicationPurposeOptions() {
  return ["", ...uniqueItems([...APPLICATION_PURPOSES, ...(state.data.applications || []).map(getApplicationPurpose)].filter(Boolean))];
}

function getApplicationProductOptions() {
  return ["", ...uniqueItems((state.data.applications || []).flatMap(getApplicationProducts).filter(Boolean))];
}

function getApplicationInitiatorSegmentOptions() {
  return ["", ...uniqueItems([
    "МСБ",
    "Корпоративный бизнес",
    "Розничный бизнес",
    "ДЗО",
    "Иной банк",
    "Автоматическое создание",
    ...(state.data.applications || []).map(getApplicationInitiatorSegment)
  ].filter(Boolean))];
}

function getApplicationContractSearchText(application) {
  return [
    application?.contractNumber,
    ...getApplicationDealRows(application).map((row) => row.contractNumber),
    ...getApplicationContracts(application).map((contract) => `${contract.id} ${contract.number}`)
  ].filter(Boolean).join(" ");
}

function getApplicationCollateralSearchText(application) {
  return getApplicationCollaterals(application)
    .map((collateral) => getCollateralRegistrySearchText(collateral))
    .join(" ");
}

function renderApplicationTaskLinks(application) {
  const tasks = getApplicationTasks(application);
  if (!tasks.length) return `<span class="muted">0 ${pluralize(0, "задача", "задачи", "задач")}</span>`;
  const visibleTask = tasks.find((task) => canViewTask(task, getRole()));
  const direction = visibleTask ? getTaskDirection(visibleTask) : getAvailableTaskDirections(getRole())[0];
  if (!direction) return `<span>${tasks.length} ${pluralize(tasks.length, "задача", "задачи", "задач")}</span>`;
  const route = getTaskDirectionConfig(direction).path;
  return renderApplicationCountLink(application, route, tasks.length, ["задача", "задачи", "задач"]);
}

function getApplicationCardRoute(application) {
  const id = application?.id || application?.number || "";
  return `/app/applications/${encodeURIComponent(id)}`;
}

function renderApplicationRegistryNumberLink(application) {
  const number = application?.number || application?.id || "-";
  if (!application) return `<span class="muted">-</span>`;
  return `<button class="link registry-object-link" data-route="${getApplicationCardRoute(application)}">${escapeHtml(number)}</button>`;
}

function renderApplicationLinkedTasksField(application) {
  const tasks = getApplicationTasks(application);
  const taskLinks = tasks.map((task) => `
    ${canViewTask(task, getRole())
      ? `<button class="link registry-object-link application-linked-task-link" data-route="/app/tasks/${escapeHtml(task.id)}">${escapeHtml(task.id)}</button>`
      : `<span class="application-linked-task-link muted">${escapeHtml(task.id)}</span>`}
  `).join("");
  return `
    <div class="application-linked-tasks-field">
      <span>Связанные задачи</span>
      <div class="application-linked-tasks-list">
        ${taskLinks || `<span class="muted">Задачи будут созданы после регистрации заявки</span>`}
      </div>
    </div>
  `;
}

function renderApplicationLinkedTasksTable(application) {
  const tasks = getApplicationTasks(application);
  return `
    <section class="application-linked-tasks-table-section">
      <div class="panel-title">
        <div>
          <h2>Связанные задачи</h2>
          <span class="panel-note">Задачи, созданные в рамках заявки.</span>
        </div>
      </div>
      ${tasks.length ? `
        <div class="application-linked-tasks-table-wrap">
          <table class="application-linked-tasks-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Номер</th>
                <th>Тип</th>
                <th>Статус</th>
                <th>Исполнитель</th>
                <th>Дата создания</th>
                <th>Срок</th>
              </tr>
            </thead>
            <tbody>
              ${tasks.map((task) => `
                <tr>
                  <td>${renderApplicationLinkedTaskIdCell(task)}</td>
                  <td>${escapeHtml(task.number || task.taskNumber || task.id || "-")}</td>
                  <td>${escapeHtml(getTaskDisplayType(task))}</td>
                  <td>${badge(task.status || "-")}</td>
                  <td>${escapeHtml(task.assignee || "-")}</td>
                  <td>${escapeHtml(getTaskCreatedDateTime(task))}</td>
                  <td>${escapeHtml(task.dueDate || "-")}</td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>
      ` : `<div class="empty-state compact">Задачи будут созданы после регистрации заявки.</div>`}
    </section>
  `;
}

function renderApplicationLinkedTaskIdCell(task) {
  const id = task?.id || "-";
  if (!task || !canViewTask(task, getRole())) return `<span class="muted">${escapeHtml(id)}</span>`;
  return `<button class="link registry-object-link application-linked-task-link" data-route="/app/tasks/${escapeHtml(id)}">${escapeHtml(id)}</button>`;
}

function renderApplicationCollateralLinks(application) {
  const collaterals = getApplicationCollaterals(application);
  return renderApplicationCountLink(application, "/app/collaterals", collaterals.length, ["залог", "залога", "залогов"]);
}

function renderApplicationContractLinks(application) {
  const contracts = getApplicationContracts(application);
  return renderContractNumberList(contracts, application?.contractNumber);
}

function renderApplicationCountLink(application, route, count, forms) {
  if (!count) return `<span class="muted">0 ${pluralize(0, forms[0], forms[1], forms[2])}</span>`;
  return `<button class="link registry-object-link" data-route="${route}?applicationNumber=${encodeURIComponent(application.number)}">${count} ${pluralize(count, forms[0], forms[1], forms[2])}</button>`;
}

function renderApplicationsRegistry() {
  const role = getRole();
  const filters = state.filters.applications;
  const rows = (state.data.applications || []).filter((application) =>
    matches(application.number || application.id, filters.number)
    && matches(getApplicationType(application), filters.type)
    && matches(getApplicationSubtype(application), filters.subtype)
    && matches(getApplicationPurpose(application), filters.purpose)
    && matches(getApplicationInitiator(application), filters.initiator)
    && matches(getApplicationInitiatorSegment(application), filters.initiatorSegment)
    && matches(getApplicationClientName(application), filters.clientName)
    && matches(getApplicationInn(application), filters.inn)
    && matches(getApplicationProductSummary(application), filters.product)
    && matches(application.status, filters.status)
    && matches(getApplicationContractSearchText(application), filters.contractNumber)
    && matches(getApplicationCollateralSearchText(application), filters.collateralId)
    && matchesDateOnlyRange(getApplicationCreatedDate(application), filters.createdFrom, filters.createdTo)
  );
  return `
    <section class="registry-work-area registry-work-area-applications">
      ${renderPageHeader("Реестр заявок", "Заявки, по которым выполняются задачи залоговой службы.",
        hasPermission(role, "appCreateEdit") ? `<button class="btn btn-primary" data-route="/app/applications/new">Создать заявку</button>` : "")}
      <section class="panel">
        <div class="filter-grid registry-filter-grid applications-filter-grid">
          ${filterInput("applications", "number", "Номер заявки")}
          ${filterSelect("applications", "type", "Тип заявки", getApplicationTypeFilterOptions())}
          ${filterSelect("applications", "subtype", "Подтип заявки", getApplicationSubtypeFilterOptions())}
          ${filterSelect("applications", "purpose", "Цель", getApplicationPurposeOptions())}
          ${filterInput("applications", "initiator", "Инициатор")}
          ${filterSelect("applications", "initiatorSegment", "Сегмент инициатора", getApplicationInitiatorSegmentOptions())}
          ${filterInput("applications", "clientName", "Клиент")}
          ${filterInput("applications", "inn", "ИНН")}
          ${filterSelect("applications", "product", "Продукты", getApplicationProductOptions())}
          ${filterSelect("applications", "status", "Статус заявки", getApplicationStatusOptions())}
          ${filterInput("applications", "contractNumber", "Номер договора")}
          ${filterInput("applications", "collateralId", "Залог")}
          ${filterDateRange("applications", "createdFrom", "createdTo", "Дата создания")}
          <button class="btn btn-secondary" data-action="reset-filters" data-scope="applications">Сбросить</button>
        </div>
      </section>
      <section class="panel table-panel" data-registry-table="applications" tabindex="-1">
        <div class="panel-title"><h2>Заявки</h2><span class="panel-note">${rows.length} записей</span></div>
        <table class="applications-table">
          <thead><tr><th>Заявка</th><th>Дата создания</th><th>Тип</th><th>Подтип</th><th>Цель</th><th>Инициатор</th><th>Сегмент инициатора</th><th>Клиент</th><th>ИНН</th><th>Статус заявки</th><th>Задачи</th><th>Залог</th></tr></thead>
          <tbody>${rows.length ? rows.map((application) => `
            <tr>
              <td>${renderApplicationRegistryNumberLink(application)}</td>
              <td>${escapeHtml(getApplicationCreatedDate(application))}</td>
              <td>${escapeHtml(getApplicationType(application))}</td>
              <td>${escapeHtml(getApplicationSubtype(application))}</td>
              <td>${escapeHtml(getApplicationPurpose(application))}</td>
              <td>${escapeHtml(getApplicationInitiator(application))}</td>
              <td>${escapeHtml(getApplicationInitiatorSegment(application))}</td>
              <td>${escapeHtml(getApplicationClientName(application))}</td>
              <td>${escapeHtml(getApplicationInn(application))}</td>
              <td>${badge(application.status)}</td>
              <td>${renderApplicationTaskLinks(application)}</td>
              <td>${renderApplicationCollateralLinks(application)}</td>
            </tr>
          `).join("") : `<tr><td colspan="12"><span class="muted">Заявки не найдены</span></td></tr>`}</tbody>
        </table>
      </section>
    </section>
  `;
}

function renderCollateralControlPanel(rows, activeKpi = "") {
  const controlRows = getCollateralControlRows(rows);
  return `
    <section class="panel chart-panel collateral-control-panel">
      <div class="panel-title">
        <div>
          <h2>Контроль залогов по видам имущества</h2>
        </div>
        <span class="panel-note">${controlRows.length} типов</span>
      </div>
      <div class="collateral-control-grid">
        <div class="collateral-control-head" aria-hidden="true">
          <span>Вид имущества</span>
          <span>Залоговая стоимость</span>
          <span>Контрольные сигналы</span>
        </div>
        ${controlRows.length ? controlRows.map((row) => {
          const controlFilter = getCollateralControlKpi(row.type);
          return `
          <button type="button" class="collateral-control-row ${row.tone} ${activeKpi === controlFilter ? "active" : ""}" data-action="registry-kpi" data-scope="collaterals" data-filter="kpi" data-value="${escapeHtml(controlFilter)}">
            <span class="collateral-control-type">
              <strong>${escapeHtml(row.type)}</strong>
              <small>${row.count} шт. · с сигналами: ${row.attentionCount}</small>
            </span>
            <span class="collateral-control-value">
              <span class="collateral-control-bar"><i style="width:${row.share}%"></i></span>
              <strong>${escapeHtml(formatShortMoney(row.pledgeValue))}</strong>
            </span>
            <span class="collateral-control-signals">
              ${renderCollateralControlMetric(row.criticalCount, "Риск", "danger")}
              ${renderCollateralControlMetric(row.appraisalCount, "Оценка", "warning")}
              ${renderCollateralControlMetric(row.insuranceCount, "Полис", "warning")}
              ${renderCollateralControlMetric(row.monitoringCount, "Осмотр", "warning")}
            </span>
          </button>
        `;
        }).join("") : `<div class="empty-state">Нет объектов в выбранном срезе</div>`}
      </div>
    </section>
  `;
}

function getCollateralControlKpi(type) {
  return `control:${type}`;
}

function getCollateralControlKpiType(kpi) {
  const prefix = "control:";
  return String(kpi || "").startsWith(prefix) ? String(kpi).slice(prefix.length) : "";
}

function getCollateralControlRows(rows) {
  const totalPledge = sumBy(rows, (item) => item.pledgeValue);
  const grouped = rows.reduce((acc, item) => {
    acc[item.type] = acc[item.type] || [];
    acc[item.type].push(item);
    return acc;
  }, {});
  return Object.entries(grouped).map(([type, items]) => {
    const pledgeValue = sumBy(items, (item) => item.pledgeValue);
    const criticalCount = items.filter((item) => riskTone(item) === "danger").length;
    const appraisalCount = items.filter(hasCollateralAppraisalIssue).length;
    const insuranceCount = items.filter(hasCollateralInsuranceIssue).length;
    const monitoringCount = items.filter(hasCollateralMonitoringIssue).length;
    const attentionCount = new Set(items
      .filter((item) => riskTone(item) === "danger" || hasCollateralAppraisalIssue(item) || hasCollateralInsuranceIssue(item) || hasCollateralMonitoringIssue(item))
      .map((item) => item.id)).size;
    return {
      type,
      count: items.length,
      pledgeValue,
      criticalCount,
      appraisalCount,
      insuranceCount,
      monitoringCount,
      attentionCount,
      share: totalPledge ? Math.max(3, Math.round((pledgeValue / totalPledge) * 100)) : 0,
      tone: criticalCount ? "danger" : attentionCount ? "warning" : "ok"
    };
  }).sort((a, b) =>
    b.criticalCount - a.criticalCount
    || b.attentionCount - a.attentionCount
    || b.pledgeValue - a.pledgeValue
    || a.type.localeCompare(b.type, "ru")
  );
}

function renderCollateralControlMetric(value, label, tone) {
  return `
    <span class="collateral-control-metric ${value ? tone : "ok"}">
      <strong>${value}</strong>
      <small>${escapeHtml(label)}</small>
    </span>
  `;
}

function hasCollateralAppraisalIssue(collateral) {
  return collateral.appraisalStatus === "Истекает" || collateral.appraisalStatus === "Просрочена";
}

function hasCollateralInsuranceIssue(collateral) {
  const premiumStatus = collateral.insurance?.premiumStatus || "";
  return collateral.insuranceStatus === "Истекает"
    || collateral.insuranceStatus === "Не оплачена"
    || (premiumStatus && premiumStatus !== "Оплачена");
}

function hasCollateralMonitoringIssue(collateral) {
  const nextInspectionDays = daysUntil(collateral.monitoring?.nextInspection);
  return nextInspectionDays !== null && nextInspectionDays <= 30;
}

function daysUntil(dateValue) {
  const date = new Date(dateValue);
  if (Number.isNaN(date.getTime())) return null;
  const today = new Date("2026-06-18T00:00:00");
  return Math.ceil((date - today) / 86400000);
}

function getInsurancePolicyRows() {
  return state.data.collaterals.map((collateral) => {
    const insurance = collateral.insurance || {};
    const contract = getContract(collateral.contractIds?.[0]);
    const due = insurance.to || collateral.insuranceDue || "";
    const days = daysUntil(due);
    return {
      id: insurance.policy || `INS-${collateral.id}`,
      company: insurance.company || "Не выбрана",
      collateral,
      contract,
      clientId: collateral.clientId,
      clientName: collateral.clientName,
      amount: Number(insurance.amount || 0),
      premiumStatus: insurance.premiumStatus || "Не проверено",
      status: collateral.insuranceStatus || "Не указано",
      from: insurance.from || "-",
      to: due || "-",
      daysLeft: days,
      source: insurance.source || collateral.source || "-"
    };
  });
}

function renderInsurancePoliciesRegistry() {
  const filters = state.filters.insurances;
  const visual = state.visualFilters.insurances;
  const allRows = getInsurancePolicyRows();
  const filteredRows = allRows.filter((row) =>
    matches(row.id, filters.policy)
    && matches(row.clientId, filters.clientId)
    && matches(row.clientName, filters.clientName)
    && matches(row.collateral.id, filters.collateralId)
    && matches(row.company, filters.company)
    && matches(row.status, filters.status)
  );
  const expiring = filteredRows.filter((row) => matchesInsuranceKpi(row, "expiring"));
  const unpaid = filteredRows.filter((row) => matchesInsuranceKpi(row, "unpaid"));
  const baseRows = filteredRows.filter((row) => matchesInsuranceKpi(row, visual.kpi));
  const statusOptions = ["", ...new Set(allRows.map((row) => row.status))];
  return `
    ${renderPageHeader("Реестр страховых полисов", "Полисы по объектам залога, сроки действия, страховые суммы и контроль оплаты премии.")}
    ${renderKpiGrid([
      { label: "Всего полисов", value: String(filteredRows.length), hint: "По объектам залога", tone: "info" },
      { label: "Страховая сумма", value: formatShortMoney(sumBy(filteredRows, (row) => row.amount)), hint: "Сумма по фильтру", tone: "info" },
      { label: "Истекают до 30 дней", value: String(expiring.length), hint: "Контроль срока", tone: expiring.length ? "warn" : "info", active: visual.kpi === "expiring", action: 'data-action="registry-kpi" data-scope="insurances" data-filter="kpi" data-value="expiring"' },
      { label: "Премия не оплачена", value: String(unpaid.length), hint: "Требует обработки", tone: unpaid.length ? "danger" : "info", active: visual.kpi === "unpaid", action: 'data-action="registry-kpi" data-scope="insurances" data-filter="kpi" data-value="unpaid"' }
    ])}
    <section class="panel">
      <div class="filter-grid registry-filter-grid">
        ${filterInput("insurances", "policy", "Номер полиса")}
        ${filterInput("insurances", "clientId", "ИНН страхователя")}
        ${filterInput("insurances", "clientName", "Страхователь")}
        ${filterInput("insurances", "collateralId", "Идентификатор залога")}
        ${filterInput("insurances", "company", "Страховая компания")}
        ${filterSelect("insurances", "status", "Статус полиса", statusOptions)}
        <button class="btn btn-secondary" data-action="reset-filters" data-scope="insurances">Сбросить</button>
      </div>
    </section>
    <section class="panel table-panel" data-registry-table="insurances" tabindex="-1">
      <div class="panel-title"><h2>Страховые полисы</h2><span class="panel-note">${baseRows.length} строк</span></div>
      <table>
        <thead><tr><th>Полис</th><th>Объект залога</th><th>Страхователь</th><th>Договор</th><th>Компания</th><th>Срок</th><th>Сумма</th><th>Премия</th><th>Статус</th><th>Источник</th></tr></thead>
        <tbody>${baseRows.map((row) => `
          <tr>
            <td><a class="link registry-object-link" href="#/app/collaterals/${escapeHtml(row.collateral.id)}?tab=insurance">${escapeHtml(row.id)}</a></td>
            <td>${escapeHtml(row.collateral.id)}<br><small>${escapeHtml(row.collateral.description)}</small></td>
            <td>${escapeHtml(row.clientName)}<br><small>${escapeHtml(row.collateral.clientId)}</small></td>
            <td>${row.contract ? escapeHtml(row.contract.number) : "-"}</td>
            <td>${escapeHtml(row.company)}</td>
            <td>${escapeHtml(row.from)} - ${escapeHtml(row.to)}<br><small>${row.daysLeft === null ? "Срок не рассчитан" : `${row.daysLeft} дн.`}</small></td>
            <td>${formatMoney(row.amount)}</td>
            <td>${badge(row.premiumStatus)}</td>
            <td>${badge(row.status)}</td>
            <td>${escapeHtml(row.source)}</td>
          </tr>
        `).join("")}</tbody>
      </table>
    </section>
  `;
}

function getTaskSourceCount(channel) {
  const aliases = {
    manual: ["Вручную"],
    excel: ["Excel"],
    email: ["Email", "Почтовый сервер"],
    pipeline: ["Конвейер"],
    schedule: ["Расписание", "Планировщик"],
    trigger: ["Триггер", "Авито", "Авто.ру", "Яндекс Недвижимость", "Циан", "ЕГРН", "Инфосфера"]
  }[channel.id] || [channel.name];
  return state.data.tasks.filter((task) => aliases.some((alias) => String(task.source || "").includes(alias) || (task.route || []).some((step) => String(step).includes(alias)))).length;
}

