function renderCollateralRegistryPickerModal() {
  const search = state.modal.search || "";
  const dealIndex = getModalApplicationDealIndex();
  const dealRow = getApplicationDealByIndex(dealIndex);
  const isDealContext = Boolean(dealRow);
  const selected = new Set(isDealContext ? (dealRow.collateralIds || []) : (state.newTask.selectedCollateralIds || []));
  const rows = state.data.collaterals.filter((item) => {
    const haystack = [item.id, getCollateralTypeLabel(item), getCollateralObjectIdentifier(item), item.description, item.address, item.clientName, item.clientId].join(" ");
    return matches(haystack, search);
  });
  return `
    <div class="modal-backdrop">
      <section class="modal wide">
        <div class="modal-head"><h2>${isDealContext ? "Выбрать объект залога" : "Выбрать из реестра залогов"}</h2><button class="btn btn-secondary" data-action="close-modal">Закрыть</button></div>
        ${isDealContext ? `<p class="hint">Строка договора: ${escapeHtml(getApplicationDealTargetLabel(dealRow, dealIndex))}</p>` : ""}
        <div class="task-pool-search">
          <label>Поиск по ID, профильному идентификатору, залогодателю, адресу или виду залога<input value="${escapeHtml(search)}" data-modal-collateral-search></label>
          <span>${rows.length} объектов найдено</span>
        </div>
        <div class="table-wrap collateral-picker-table">
          <table>
            <thead><tr><th></th><th>ID</th><th>Вид залога</th><th>Профильный идентификатор</th><th>Объект</th><th>Залогодатель</th><th>Залоговая стоимость</th><th>Риск</th></tr></thead>
            <tbody>${rows.map((item) => `
              <tr>
                <td><input type="checkbox" data-modal-collateral-choice="${escapeHtml(item.id)}" ${selected.has(item.id) ? "checked" : ""}></td>
                <td><strong>${escapeHtml(item.id)}</strong></td>
                <td>${escapeHtml(getCollateralTypeLabel(item))}</td>
                <td>${escapeHtml(getCollateralObjectIdentifier(item))}</td>
                <td>${escapeHtml(item.description)}<br><small>${escapeHtml(item.address)}</small></td>
                <td>${escapeHtml(item.clientName)}<br><small>${escapeHtml(item.clientId)}</small></td>
                <td>${formatMoney(item.pledgeValue || 0)}</td>
                <td>${badge(getCollateralRiskState(item), riskTone(item))}</td>
              </tr>
            `).join("")}</tbody>
          </table>
        </div>
        <div class="modal-actions"><button class="btn btn-primary" data-action="submit-collateral-picker">${isDealContext ? "Применить к строке договора" : "Добавить выбранные"}</button></div>
      </section>
    </div>
  `;
}

